package stratagit

import (
	"context"
	"errors"
	"fmt"
	"io"
	"maps"
	"net/http"
	"net/url"
	"strings"
	"sync"

	"github.com/entirehq/strata/git"
	"github.com/go-git/go-git/v6/config"
	"github.com/go-git/go-git/v6/plumbing"
	"github.com/go-git/go-git/v6/plumbing/client"
	"github.com/go-git/go-git/v6/plumbing/format/packfile"
	"github.com/go-git/go-git/v6/plumbing/object"
	"github.com/go-git/go-git/v6/plumbing/protocol"
	"github.com/go-git/go-git/v6/plumbing/protocol/capability"
	"github.com/go-git/go-git/v6/plumbing/protocol/packp"
	"github.com/go-git/go-git/v6/plumbing/revlist"
	"github.com/go-git/go-git/v6/plumbing/storer"
	"github.com/go-git/go-git/v6/plumbing/transport"
	"github.com/go-git/go-git/v6/storage"
	"github.com/go-git/go-git/v6/storage/memory"
)

// Transport is git.Transport over go-git's smart-HTTP client, for this package's
// repositories only: git.Repo cannot take in a pack, so fetched objects go
// straight into a Repo's storage.
type Transport struct {
	Client *http.Client
	// Context bounds every round trip, since strata's Transport methods take
	// none. Nil means context.Background.
	Context context.Context
}

var _ git.Transport = Transport{}

func (t Transport) ctx() context.Context {
	if t.Context == nil {
		return context.Background()
	}
	return t.Context
}

func (Transport) url(repo git.Repo, remote string) (*url.URL, error) {
	raw, err := repo.ConfigGet(remoteKey(remote, "url"))
	if err != nil {
		return nil, err
	}
	if raw == "" {
		return nil, fmt.Errorf("stratagit: remote %s has no url", remote)
	}
	return transport.ParseURL(raw)
}

func (Transport) own(repo git.Repo) (*Repo, error) {
	r, ok := repo.(*Repo)
	if !ok {
		return nil, fmt.Errorf("stratagit: transport needs a stratagit repository, got %T", repo)
	}
	return r, nil
}

func (t Transport) session(repo git.Repo, remote, svc string) (transport.Session, error) {
	ep, err := t.url(repo, remote)
	if err != nil {
		return nil, err
	}
	var opts []client.Option
	if t.Client != nil {
		opts = append(opts, client.WithHTTPClient(t.Client))
	}
	req := &transport.Request{URL: ep, Command: svc}
	if svc == transport.UploadPackService {
		// v2, so ref discovery takes prefixes. There is no v2 push.
		req.Protocol = protocol.V2
	}
	return client.New(opts...).Handshake(t.ctx(), req)
}

// Caps falls back to upload-pack when receive-pack discovery is refused: strata
// asks before a fetch too, and entiredb refuses receive-pack to a caller who may
// only read. ReportStatus is then reported held, since such a caller can't land
// a push; Push checks the real advertisement before it sends anything.
func (t Transport) Caps(repo git.Repo, remote string) (git.Caps, error) {
	sess, err := t.session(repo, remote, transport.ReceivePackService)
	if errors.Is(err, transport.ErrAuthorizationFailed) || errors.Is(err, transport.ErrAuthenticationRequired) {
		read, rerr := t.session(repo, remote, transport.UploadPackService)
		if rerr != nil {
			return git.Caps{}, rerr
		}
		_ = read.Close()
		return git.Caps{ReportStatus: true}, nil
	}
	if err != nil {
		return git.Caps{}, err
	}
	defer func() { _ = sess.Close() }()
	return capsOf(sess), nil
}

func capsOf(sess transport.Session) git.Caps {
	caps := sess.Capabilities()
	return git.Caps{
		Atomic:       caps.Supports(capability.Atomic),
		ReportStatus: caps.Supports(capability.ReportStatus),
	}
}

func (t Transport) LsRemote(repo git.Repo, remote, prefix string) (map[string]string, error) {
	sess, err := t.session(repo, remote, transport.UploadPackService)
	if err != nil {
		return nil, err
	}
	defer func() { _ = sess.Close() }()
	prefix = git.Prefix(prefix)
	// The prefix goes without a trailing slash so an exact ref is included;
	// under drops the siblings that also lets through.
	var filter []string
	if prefix != "" {
		filter = []string{prefix}
	}
	refs, err := t.list(sess, filter)
	if err != nil {
		return nil, err
	}
	out := map[string]string{}
	for _, r := range refs {
		// An unborn HEAD arrives with no object.
		if r.Hash().IsZero() {
			continue
		}
		if name := r.Name().String(); under(prefix, name) {
			out[name] = r.Hash().String()
		}
	}
	return out, nil
}

func (t Transport) Push(repo git.Repo, remote string, publish []string, withdraw []git.Withdrawal) error {
	if len(publish) == 0 && len(withdraw) == 0 {
		return nil
	}
	ctx := t.ctx()
	sess, err := t.session(repo, remote, transport.ReceivePackService)
	if err != nil {
		return err
	}
	defer func() { _ = sess.Close() }()
	// Again here, as Caps may not have seen this advertisement. Without
	// report-status go-git reports success unread.
	if err := capsOf(sess).Require(remote); err != nil {
		return err
	}

	advertised, err := sess.GetRemoteRefs(ctx, nil)
	if err != nil {
		return err
	}
	old := map[string]plumbing.Hash{}
	for _, r := range advertised.References {
		old[r.Name().String()] = r.Hash()
	}
	r, err := t.own(repo)
	if err != nil {
		return err
	}
	st := r.objects()

	var cmds []*packp.Command
	var wants, haves []plumbing.Hash
	var refused []string
	for _, ref := range publish {
		oid, err := repo.Ref(ref)
		if err != nil {
			return err
		}
		if oid == "" {
			return fmt.Errorf("stratagit: %s does not exist locally", ref)
		}
		h := plumbing.NewHash(oid)
		prev := old[ref]
		if prev == h {
			continue
		}
		// Old from the advertisement makes the push a compare-and-swap.
		// receive-pack enforces only that; refusing a non-fast-forward is
		// send-pack's job, and strata relies on it to arbitrate racing
		// compactors (its ADR-0010).
		if !prev.IsZero() && prev != h {
			ff, err := fastForward(st, prev, h)
			if err != nil {
				return fmt.Errorf("stratagit: %s: checking %s is a fast-forward of %s: %w", ref, h, prev, err)
			}
			if !ff {
				refused = append(refused, fmt.Sprintf("%s: %s is not a fast-forward of %s", ref, h, prev))
				continue
			}
		}
		cmds = append(cmds, &packp.Command{Name: plumbing.ReferenceName(ref), Old: prev, New: h})
		wants = append(wants, h)
		// Only the pushed refs' remote tips, as send-pack does: every
		// advertised ref would cost a walk per held tip.
		if !prev.IsZero() {
			haves = append(haves, prev)
		}
	}
	for _, w := range withdraw {
		// receive-pack checks only its own advertisement, so the lease is checked
		// here. An absent ref fails it, as with --force-with-lease.
		if w.Old != "" && old[w.Ref] != plumbing.NewHash(w.Old) {
			refused = append(refused, fmt.Sprintf("%s: stale info, holds %s and the lease was %s", w.Ref, old[w.Ref], w.Old))
			continue
		}
		// Already gone. A zero-to-zero command would make go-git refuse the
		// whole push.
		if old[w.Ref].IsZero() {
			continue
		}
		cmds = append(cmds, &packp.Command{Name: plumbing.ReferenceName(w.Ref), Old: old[w.Ref], New: plumbing.ZeroHash})
	}
	if len(cmds) == 0 {
		return refusal(refused)
	}

	req := &transport.PushRequest{Commands: cmds}
	// finish waits for the pack encoder's goroutine on every path, so it never
	// reads the store after Push returns; closing the pipe stops it.
	finish := func() error { return nil }
	if len(wants) > 0 {
		hashes, err := revlist.Objects(st, wants, haves)
		if err != nil {
			return fmt.Errorf("stratagit: selecting objects to send: %w", err)
		}
		rd, wr := io.Pipe()
		req.Packfile = rd
		encoded := make(chan error, 1)
		go func() {
			enc := packfile.NewEncoder(wr, st, !sess.Capabilities().Supports(capability.OFSDelta))
			if _, err := enc.Encode(hashes, 10); err != nil {
				encoded <- wr.CloseWithError(err)
				return
			}
			encoded <- wr.Close()
		}()
		finish = func() error {
			_ = rd.Close()
			return <-encoded
		}
	}
	err = sess.Push(ctx, st, req)
	encErr := finish()
	if err != nil {
		return classifyPush(err)
	}
	if encErr != nil {
		return encErr
	}
	return refusal(refused)
}

func refusal(refused []string) error {
	if len(refused) == 0 {
		return nil
	}
	return fmt.Errorf("stratagit: push refused: %w: %s", git.ErrRejected, strings.Join(refused, "; "))
}

// classifyPush maps a refused ref to ErrRejected. A report-status "ng" arrives
// typed whatever the server's words; the wording check covers refusals that
// don't.
func classifyPush(err error) error {
	var refused packp.CommandStatusErr
	if errors.As(err, &refused) {
		return fmt.Errorf("stratagit: push refused: %w: %s", git.ErrRejected, err)
	}
	msg := strings.ToLower(err.Error())
	for _, m := range []string{"non-fast-forward", "already exists", "rejected", "failed to update", "cannot lock"} {
		if strings.Contains(msg, m) {
			return fmt.Errorf("stratagit: push refused: %w: %s", git.ErrRejected, err)
		}
	}
	return fmt.Errorf("stratagit: push: %w", err)
}

const fetchAttempts = 3

// Fetch starts over when an advertised ref is deleted before its want arrives,
// as git.Transport requires. A failed attempt leaves nothing behind (see staged).
func (t Transport) Fetch(repo git.Repo, remote string, refspecs ...string) error {
	return retryVanished(func() error { return t.fetch(repo, remote, refspecs...) })
}

// retryVanished runs try again, up to fetchAttempts in all, while it fails
// because a ref vanished between the listing and the fetch.
func retryVanished(try func() error) error {
	for attempt := 1; ; attempt++ {
		err := try()
		if err == nil || attempt == fetchAttempts || !vanished(err) {
			return err
		}
	}
}

// vanished matches git's "not our ref", which entiredb sends verbatim; there is
// no typed form.
func vanished(err error) bool {
	return strings.Contains(err.Error(), "not our ref")
}

// fetch takes every advertised ref, offering the tracking refs already held as
// haves.
func (t Transport) fetch(repo git.Repo, remote string, refspecs ...string) error {
	r, err := t.own(repo)
	if err != nil {
		return err
	}
	r.mu.RLock()
	partial := r.partial
	r.mu.RUnlock()
	if partial {
		return errors.New("stratagit: a clone fetched for one incremental read cannot be fetched into")
	}
	sess, err := t.session(repo, remote, transport.UploadPackService)
	if err != nil {
		return err
	}
	defer func() { _ = sess.Close() }()
	specs := parseRefspecs(refspecs)
	advertised, err := t.list(sess, specs.sources)
	if err != nil {
		return err
	}
	held, err := specs.held(repo)
	if err != nil {
		return err
	}
	haves := make([]plumbing.Hash, 0, len(held))
	for _, oid := range held {
		haves = append(haves, plumbing.NewHash(oid))
	}
	return t.receive(sess, repo, remote, specs, advertised, nil, haves)
}

// fetchSpecs is a fetch's refspecs, with what each lists and where it lands.
type fetchSpecs struct {
	specs []config.RefSpec
	// sources become ls-refs prefixes, so a fetch lists only that store's refs.
	sources, scopes []string
}

func parseRefspecs(refspecs []string) fetchSpecs {
	var out fetchSpecs
	for _, raw := range refspecs {
		spec := config.RefSpec(strings.TrimPrefix(raw, "+"))
		out.specs = append(out.specs, spec)
		src, dst, _ := strings.Cut(string(spec), ":")
		out.sources = append(out.sources, strings.TrimSuffix(src, "*"))
		if dst != "" {
			out.scopes = append(out.scopes, strings.TrimSuffix(dst, "*"))
		}
	}
	return out
}

// held is the tracking refs the specs land in, as they stand.
func (f fetchSpecs) held(repo git.Repo) (map[string]string, error) {
	out := map[string]string{}
	for _, scope := range f.scopes {
		refs, err := repo.Refs(git.Prefix(scope))
		if err != nil {
			return nil, err
		}
		maps.Copy(out, refs)
	}
	return out, nil
}

// list asks the remote for its refs under prefixes. An empty remote is normal
// for a new store, and lists as nothing.
func (t Transport) list(sess transport.Session, prefixes []string) ([]*plumbing.Reference, error) {
	refs, err := sess.GetRemoteRefs(t.ctx(), &transport.GetRemoteRefsOptions{RefPrefixes: prefixes})
	switch {
	case err == nil:
		return refs.References, nil
	case errors.Is(err, transport.ErrEmptyRemoteRepository):
		return nil, nil
	}
	return nil, err
}

// receive fetches, from what was advertised, the refs want takes (all of them
// when want is nil), offering haves, which the repository need not hold: a
// read that stops at them never asks for what lies behind them (strata
// ADR-0025). Every advertised ref lands as a tracking ref, fetched or not, and
// a tracking ref no longer advertised is pruned. With a want, the repository
// is left partial (Repo.partial), and the invariant staged keeps does not hold
// for it.
func (t Transport) receive(sess transport.Session, repo git.Repo, remote string, specs fetchSpecs,
	advertised []*plumbing.Reference, want func(ref string) bool, haves []plumbing.Hash) error {
	r, err := t.own(repo)
	if err != nil {
		return err
	}
	if want != nil {
		r.mu.Lock()
		r.partial = true
		r.mu.Unlock()
	}
	st := r.objects()

	wanted := map[string]plumbing.Hash{}
	missing := map[plumbing.Hash]bool{}
	for _, spec := range specs.specs {
		for _, r := range advertised {
			if r.Type() != plumbing.HashReference || !spec.Match(r.Name()) {
				continue
			}
			wanted[spec.Dst(r.Name()).String()] = r.Hash()
			if want != nil && !want(r.Name().String()) {
				continue
			}
			if !missing[r.Hash()] && st.HasEncodedObject(r.Hash()) != nil {
				missing[r.Hash()] = true
			}
		}
	}

	held, err := specs.held(repo)
	if err != nil {
		return err
	}
	var ops []git.RefOp
	for name, oid := range held {
		want, keep := wanted[name]
		switch {
		case !keep:
			ops = append(ops, git.RefOp{Kind: git.RefDelete, Ref: name, Old: oid})
		case want.String() != oid:
			ops = append(ops, git.RefOp{Kind: git.RefUpdate, Ref: name, New: want.String(), Old: oid})
		}
		delete(wanted, name)
	}
	if len(missing) > 0 {
		wants := make([]plumbing.Hash, 0, len(missing))
		for h := range missing {
			wants = append(wants, h)
		}
		pending, err := stage(st)
		if err != nil {
			return err
		}
		err = sess.Fetch(t.ctx(), pending, &transport.FetchRequest{Wants: wants, Haves: haves})
		if err != nil && !errors.Is(err, transport.ErrNoChange) {
			return fmt.Errorf("stratagit: fetching from %s: %w", remote, err)
		}
		err = pending.commit(&r.mu)
		if err != nil {
			return err
		}
	}
	for name, h := range wanted {
		ops = append(ops, git.RefOp{Kind: git.RefCreate, Ref: name, New: h.String()})
	}
	if len(ops) == 0 {
		return nil
	}
	return repo.ApplyRefOps(ops)
}

// staged holds one fetch's objects until the whole pack has arrived. go-git
// stores each object as it parses, so a broken pack would otherwise leave a tip
// held without its history, and the next fetch would skip it. Staging keeps
// the invariant the skip relies on: a held object has everything it reaches.
// A partial clone breaks it by design, which is why one is never fetched into.
//
// Objects land before refs, as in git. If ApplyRefOps then fails, the objects
// are complete but unreferenced, and the next fetch publishes the ref.
type staged struct {
	*memory.Storage // what this fetch has written
	base            objects
}

func stage(base objects) (*staged, error) {
	cfg, err := base.Config()
	if err != nil {
		return nil, err
	}
	pending := memory.NewStorage()
	if err := pending.SetObjectFormat(cfg.Extensions.ObjectFormat); err != nil {
		return nil, fmt.Errorf("stratagit: %w", err)
	}
	return &staged{Storage: pending, base: base}, nil
}

// Reads fall through to the repository: a thin pack's deltas name bases it holds.

func (s *staged) HasEncodedObject(h plumbing.Hash) error {
	if s.Storage.HasEncodedObject(h) == nil {
		return nil
	}
	return s.base.HasEncodedObject(h)
}

func (s *staged) EncodedObjectSize(h plumbing.Hash) (int64, error) {
	if n, err := s.Storage.EncodedObjectSize(h); err == nil {
		return n, nil
	}
	return s.base.EncodedObjectSize(h)
}

func (s *staged) EncodedObject(t plumbing.ObjectType, h plumbing.Hash) (plumbing.EncodedObject, error) {
	if o, err := s.Storage.EncodedObject(t, h); err == nil {
		return o, nil
	}
	return s.base.EncodedObject(t, h)
}

func (s *staged) commit(mu *sync.RWMutex) error {
	iter, err := s.IterEncodedObjects(plumbing.AnyObject)
	if err != nil {
		return err
	}
	mu.Lock()
	defer mu.Unlock()
	return iter.ForEach(func(o plumbing.EncodedObject) error {
		_, err := s.base.Storage.SetEncodedObject(o)
		return err
	})
}

// objects locks each read of the object store rather than the whole transfer,
// so a slow remote doesn't stall writers. That suffices because objects never
// change once written.
type objects struct {
	*memory.Storage
	mu *sync.RWMutex
}

func (r *Repo) objects() objects { return objects{Storage: r.store, mu: &r.mu} }

func (o objects) SetEncodedObject(obj plumbing.EncodedObject) (plumbing.Hash, error) {
	o.mu.Lock()
	defer o.mu.Unlock()
	return o.Storage.SetEncodedObject(obj)
}

func (o objects) EncodedObject(t plumbing.ObjectType, h plumbing.Hash) (plumbing.EncodedObject, error) {
	o.mu.RLock()
	defer o.mu.RUnlock()
	return o.Storage.EncodedObject(t, h)
}

func (o objects) HasEncodedObject(h plumbing.Hash) error {
	o.mu.RLock()
	defer o.mu.RUnlock()
	return o.Storage.HasEncodedObject(h)
}

func (o objects) EncodedObjectSize(h plumbing.Hash) (int64, error) {
	o.mu.RLock()
	defer o.mu.RUnlock()
	return o.Storage.EncodedObjectSize(h)
}

// IterEncodedObjects is safe to use after unlocking: memory storage returns a
// snapshot slice, not a view of its maps.
func (o objects) IterEncodedObjects(t plumbing.ObjectType) (storer.EncodedObjectIter, error) {
	o.mu.RLock()
	defer o.mu.RUnlock()
	return o.Storage.IterEncodedObjects(t)
}

// fastForward is false when old isn't held, as git's "fetch first".
func fastForward(st storage.Storer, old, new plumbing.Hash) (bool, error) {
	newC, err := object.GetCommit(st, new)
	if err != nil {
		return false, err
	}
	oldC, err := object.GetCommit(st, old)
	if errors.Is(err, plumbing.ErrObjectNotFound) {
		return false, nil
	}
	if err != nil {
		return false, err
	}
	return oldC.IsAncestor(newC)
}

