package stratagit

import (
	"context"
	"errors"
	"fmt"
	"log/slog"
	"net/http"

	"github.com/entirehq/strata/git"
	"github.com/entirehq/strata/project"
	"github.com/entirehq/strata/reflayout"
	"github.com/entirehq/strata/settings"
	strata "github.com/entirehq/strata/store"
	"github.com/go-git/go-git/v6/plumbing"
	"github.com/go-git/go-git/v6/plumbing/transport"
)

// Remote is one repository's git endpoint, reached as one caller. Strata reads
// and writes both go through it rather than the repo API, whose JSON pages cap a
// commit message at 64 KiB: a strata log entry carries its payload there.
type Remote struct {
	URL string
	// Client carries the caller's credentials (httpapi's contentHTTPClient).
	Client *http.Client
}

// Origin is the name a Remote's repository is configured under in a clone.
const Origin = "origin"

// Open fetches one store into a fresh in-memory clone. The clone holds no
// connection or goroutine, so dropping the Store is all the cleanup it needs.
func (r Remote) Open(ctx context.Context, store string) (*strata.Store, error) {
	s, _, err := r.clone(ctx, store)
	if err != nil {
		return nil, err
	}
	if err := s.Fetch(Origin); err != nil {
		return nil, fmt.Errorf("stratagit: fetching %s: %w", store, err)
	}
	return s, nil
}

// clone is a fresh in-memory clone of one store with origin configured, and
// nothing fetched.
func (r Remote) clone(ctx context.Context, store string) (*strata.Store, *Repo, error) {
	d := NewDriver()
	const dir = "/strata"
	repo, err := d.Init(dir, git.InitOptions{})
	if err != nil {
		return nil, nil, err
	}
	s, err := strata.Open(d, r.transport(ctx), dir, store, settings.Settings{})
	if err != nil {
		return nil, nil, fmt.Errorf("stratagit: opening %s: %w", store, err)
	}
	if err := s.Configure(Origin, r.URL); err != nil {
		return nil, nil, err
	}
	return s, repo.(*Repo), nil
}

// Read is how FeedSince reached the store. Zero is no read.
type Read uint8

const (
	// ReadUnmoved fetched nothing: the store is where since left it.
	ReadUnmoved Read = iota + 1
	ReadIncremental
	// ReadWhole is a first read, or one after a change strata reads whole: a
	// new generation, a rotated or deleted log.
	ReadWhole
	// ReadWholeAfterRefusal is an incremental read strata refused, read again
	// whole.
	ReadWholeAfterRefusal
)

func (r Read) String() string {
	switch r {
	case ReadUnmoved:
		return "unmoved"
	case ReadIncremental:
		return "incremental"
	case ReadWhole:
		return "whole"
	case ReadWholeAfterRefusal:
		return "whole_after_refusal"
	}
	return ""
}

// FeedSince is strata's FeedSince for a reader that keeps nothing between
// reads but since: it fetches into a fresh clone only what reading on needs --
// the new entries on the logs that grew, or everything when the store changed
// in a way strata reads whole -- and reads it. On ReadUnmoved nothing was
// fetched, and the batch and next are empty.
//
// ErrNotIncremental is answered by reading whole, which is always right. Since
// strata plans the fetch and the read from one listing, needing it means the
// read did not stand where since says: a fetch that missed an entry, or a
// cursor behind since's generation. Either is worth knowing.
func (r Remote) FeedSince(ctx context.Context, store string, c project.Cursor, since strata.Since) (project.Batch, strata.Since, Read, error) {
	b, next, read, err := r.feedSince(ctx, store, c, since)
	if errors.Is(err, strata.ErrNotIncremental) {
		slog.WarnContext(ctx, "stratagit: could not read on; reading whole",
			slog.String("store", store), slog.Any("error", err))
		b, next, read, err = r.feedSince(ctx, store, c, strata.Since{})
		if read == ReadWhole {
			read = ReadWholeAfterRefusal
		}
	}
	return b, next, read, err
}

func (r Remote) feedSince(ctx context.Context, store string, c project.Cursor, since strata.Since) (project.Batch, strata.Since, Read, error) {
	var s *strata.Store
	var read Read
	err := retryVanished(func() (err error) {
		s, _, read, err = r.fetchSince(ctx, store, since)
		return err
	})
	if err != nil || read == ReadUnmoved {
		return project.Batch{}, strata.Since{}, read, err
	}
	b, next, err := s.FeedSince(c, since)
	return b, next, read, err
}

// fetchSince lists the store and fetches what strata.FetchFor plans from that
// listing, over one session. It also returns the clone, for a test to count
// what came.
func (r Remote) fetchSince(ctx context.Context, store string, since strata.Since) (*strata.Store, *Repo, Read, error) {
	s, repo, err := r.clone(ctx, store)
	if err != nil {
		return nil, nil, 0, err
	}
	tp := r.transport(ctx)
	sess, err := tp.session(repo, Origin, transport.UploadPackService)
	if err != nil {
		return nil, nil, 0, err
	}
	defer func() { _ = sess.Close() }()
	specs := parseRefspecs([]string{reflayout.For(store).FetchRefspec(Origin)})
	advertised, err := tp.list(sess, specs.sources)
	if err != nil {
		return nil, nil, 0, fmt.Errorf("stratagit: listing %s: %w", store, err)
	}
	listed := make(map[string]string, len(advertised))
	for _, ref := range advertised {
		listed[ref.Name().String()] = ref.Hash().String()
	}
	plan := strata.FetchFor(store, since, listed)
	if plan.Incremental && len(plan.Wants) == 0 {
		return nil, nil, ReadUnmoved, nil
	}
	read := ReadWhole
	if plan.Incremental {
		read = ReadIncremental
	}
	// Haves this clone does not hold, on purpose: the remote leaves out what
	// they reach, and strata's read stops at them (ADR-0025). Nothing in the
	// pack can lean on them, since go-git never asks for a thin pack, and a
	// read that finds an entry missing is ErrNotIncremental, read again whole.
	haves := make([]plumbing.Hash, len(plan.Haves))
	for i, oid := range plan.Haves {
		haves[i] = plumbing.NewHash(oid)
	}
	wanted := func(ref string) bool { _, ok := plan.Wants[ref]; return ok }
	if err := tp.receive(sess, repo, Origin, specs, advertised, wanted, haves); err != nil {
		return nil, nil, 0, fmt.Errorf("stratagit: fetching %s: %w", store, err)
	}
	return s, repo, read, nil
}

// Refs lists the refs under prefix without fetching any objects.
func (r Remote) Refs(ctx context.Context, prefix string) (map[string]string, error) {
	repo, err := NewDriver().Init("/ls", git.InitOptions{})
	if err != nil {
		return nil, err
	}
	if err := repo.ConfigSet(remoteKey(Origin, "url"), r.URL); err != nil {
		return nil, err
	}
	return r.transport(ctx).LsRemote(repo, Origin, prefix)
}

func (r Remote) transport(ctx context.Context) Transport {
	return Transport{Client: r.Client, Context: ctx}
}

