// Package stratawrite writes entire-records stores held in strata, over git to
// entiredb. Each call writes into a fresh in-memory clone that is dropped
// afterwards, as a one-shot writer that never holds a store's compaction back.
package stratawrite

import (
	"context"
	"errors"
	"fmt"

	"github.com/entirehq/entire-records/recordapi"
	"github.com/entirehq/entire-records/schema"
	recstore "github.com/entirehq/entire-records/store"
	"github.com/entirehq/strata/git"
	strata "github.com/entirehq/strata/store"

	"github.com/entirehq/entire-api/internal/stratagit"
)

// Remote is one repository's git endpoint, reached as one caller.
type Remote stratagit.Remote

const origin = stratagit.Origin

func (r Remote) open(ctx context.Context, store string) (*strata.Store, error) {
	return stratagit.Remote(r).Open(ctx, store)
}

// Create creates a store with its schema, or updates an existing one's. It is
// safe to retry, even after ErrUnconfirmed: applying the schema a store already
// has writes nothing.
func (r Remote) Create(ctx context.Context, desired schema.Schema, author string) error {
	s, err := r.open(ctx, desired.Name)
	if err != nil {
		return err
	}
	e := recstore.OpenStore(s, recstore.SchemaRef{Name: desired.Name}, author, true)
	if _, err := e.PlanSchemaChange(desired, recstore.ApplyOptions{}); err != nil {
		return fmt.Errorf("%w: %w", ErrSchemaRefused, err)
	}
	if _, err := e.ApplySchema(ctx, desired, recstore.ApplyOptions{}); err != nil {
		return err
	}
	if err := publish(s); err != nil {
		return fmt.Errorf("stratawrite: publishing %s: %w", desired.Name, err)
	}
	return nil
}

// ErrSchemaRefused is a valid schema the store won't take against what it
// already holds.
var ErrSchemaRefused = errors.New("stratawrite: the store refuses this schema")

// OneShot applies one batch to an existing store as one commit and publishes
// it. A store nobody created fails with store.ErrNoSchema. On ErrUnconfirmed it
// still returns what it wrote, so the caller can look for it.
func (r Remote) OneShot(ctx context.Context, store string, b recordapi.Batch, author string) ([]recordapi.RecordRef, error) {
	s, err := r.open(ctx, store)
	if err != nil {
		return nil, err
	}
	e := recstore.OpenStore(s, recstore.SchemaRef{Name: store}, author, true)
	if len(b.Writes) == 0 && len(b.Deletes) == 0 {
		if err := requireSchema(e, store); err != nil {
			return nil, err
		}
		return nil, nil
	}
	written, err := recordapi.New(e).ApplyBatch(ctx, b, "")
	if err != nil {
		if noSchema := requireSchema(e, store); errors.Is(noSchema, recstore.ErrNoSchema) {
			return nil, noSchema
		}
		return nil, err
	}
	if err := publish(s); err != nil {
		err = fmt.Errorf("stratawrite: publishing %s: %w", store, err)
		if errors.Is(err, ErrUnconfirmed) {
			return written, err
		}
		return nil, err
	}
	return written, nil
}

// ErrUnconfirmed is a publish that may have landed with its answer lost. A
// retry could land a batch with minted IDs twice.
var ErrUnconfirmed = errors.New("stratawrite: the write may or may not have landed")

// publish retries an unrefused push once; create-only refs make that idempotent.
func publish(s *strata.Store) error {
	err := s.Push(origin)
	if err == nil || errors.Is(err, git.ErrRejected) {
		return err
	}
	again := s.Push(origin)
	switch {
	case again == nil:
		return nil
	case errors.Is(again, git.ErrRejected):
		// Had the first push landed, the retry would have found its refs.
		return again
	}
	return fmt.Errorf("%w: %w", ErrUnconfirmed, err)
}

func requireSchema(e *recstore.Engine, store string) error {
	sch, err := e.LoadSchema()
	if err != nil {
		return err
	}
	if len(sch.Types) == 0 {
		return fmt.Errorf("%s: %w", store, recstore.ErrNoSchema)
	}
	return nil
}

