1	package stratawrite
2	
3	import (
4		"context"
5		"errors"
6		"fmt"
7		"log/slog"
8		"slices"
9		"time"
10	
11		"github.com/entirehq/entire-records/recordapi"
12		recstore "github.com/entirehq/entire-records/store"
13		strata "github.com/entirehq/strata/store"
14	)
15	
16	// ErrFenced is a write to a writer that could not keep its lease alive.
17	var ErrFenced = errors.New("stratawrite: writer is fenced")
18	
19	// Leases is where durable writers record that they are alive (*store.RepoStore).
20	type Leases interface {
21		AcquireStrataLease(ctx context.Context, repoID, storeName, writer, replica string) error
22		RenewStrataLease(ctx context.Context, repoID, storeName, writer string) (bool, error)
23		ReleaseStrataLeases(ctx context.Context, repoID, storeName string, writers []string) error
24		LapsedStrataWriters(ctx context.Context, repoID, storeName string, after time.Duration) ([]string, error)
25		HasStrataLease(ctx context.Context, repoID, storeName, writer string) (bool, error)
26	}
27	
28	// DefaultEvictAfter is how stale a lease must be before another session evicts
29	// its writer. A writer fences itself at half of it, before anyone could.
30	const DefaultEvictAfter = 60 * time.Second
31	
32	// StaleBlockerAfter evicts a writer with no lease that holds the barrier without
33	// writing. Nothing here lapses such a writer (a local clone, a CLI), and one that
34	// walked away would otherwise stop compaction for good.
35	const StaleBlockerAfter = 24 * time.Hour
36	
37	// retainGenerations is the depth maintenance keeps, in generation numbers.
38	// Numbers skip, so this is often the newest generation alone, which is all
39	// correctness needs.
40	const retainGenerations = 2
41	
42	// Writer is one durable strata writer, held for as long as its holder lives.
43	// One goroutine owns it and calls Tick about every DefaultEvictAfter/4, so an
44	// idle writer doesn't hold the store's folds back; only Fenced and Abort may be
45	// used from elsewhere.
46	type Writer struct {
47		s            *strata.Store
48		rs           *recordapi.Records
49		leases       Leases
50		repoID       string
51		store        string
52		evict        time.Duration
53		staleBlocker time.Duration
54	
55		fenced    chan struct{}
56		stopRenew context.CancelFunc
57		close     context.CancelFunc
58		done      chan struct{}
59	}
60	
61	// Start opens a durable writer on an existing store. Its lease is taken before
62	// it announces itself.
63	func Start(ctx context.Context, r Remote, leases Leases, repoID, storeName, replica, author string, evictAfter time.Duration) (w *Writer, err error) {
64		// The writer outlives ctx, so its transport gets a context of its own, tied to
65		// ctx only while Start runs.
66		life, closeLife := context.WithCancel(context.WithoutCancel(ctx))
67		unhook := context.AfterFunc(ctx, closeLife)
68		defer func() {
69			unhook()
70			if err != nil {
71				closeLife()
72			}
73		}()
74		s, err := r.open(life, storeName)
75		if err != nil {
76			return nil, err
77		}
78		s.SetRetention(retainGenerations)
79		e := recstore.OpenStore(s, recstore.SchemaRef{Name: storeName}, author, false)
80		// Checked before announcing, so no refs land in a store nobody created.
81		if err := requireSchema(e, storeName); err != nil {
82			return nil, err
83		}
84		w = &Writer{
85			s: s, rs: recordapi.New(e), leases: leases,
86			repoID: repoID, store: storeName, evict: evictAfter, staleBlocker: StaleBlockerAfter,
87			fenced: make(chan struct{}),
88			close:  closeLife,
89			done:   make(chan struct{}),
90		}
91		if err := leases.AcquireStrataLease(ctx, repoID, storeName, w.ID(), replica); err != nil {
92			return nil, err
93		}
94		// No failure from here releases the lease: the writer may already be
95		// announced, and its lease is what lets a later session evict it. It is
96		// renewed from now on, since starting can outlast the eviction window.
97		renewCtx, stopRenew := context.WithCancel(life)
98		w.stopRenew = stopRenew
99		go w.renew(renewCtx)
100		renewed := w.done
101		defer func() {
102			if err != nil {
103				stopRenew()
104				<-renewed
105			}
106		}()
107		if err := s.Announce(origin); err != nil {
108			return nil, fmt.Errorf("stratawrite: announcing in %s: %w", storeName, err)
109		}
110		if err := w.maintain(ctx); err != nil {
111			slog.WarnContext(ctx, "stratawrite: store maintenance at start",
112				slog.String("store", storeName), slog.Any("error", err))
113		}
114		// Not handed out if the caller gave up (its transport is gone) or the lease
115		// was lost meanwhile.
116		if !unhook() {
117			return nil, fmt.Errorf("stratawrite: starting on %s: %w", storeName, context.Cause(ctx))
118		}
119		select {
120		case <-w.fenced:
121			return nil, fmt.Errorf("stratawrite: starting on %s: %w", storeName, ErrFenced)
122		default:
123		}
124		return w, nil
125	}
126	
127	func (w *Writer) ID() string { return w.s.Writer() }
128	
129	// Fenced closes when the writer stops accepting writes; its holder should end it.
130	func (w *Writer) Fenced() <-chan struct{} { return w.fenced }
131	
132	func (w *Writer) Apply(ctx context.Context, b recordapi.Batch) ([]recordapi.RecordRef, error) {
133		if err := w.live(); err != nil {
134			return nil, err
135		}
136		return w.rs.ApplyBatch(ctx, b, "")
137	}
138	
139	func (w *Writer) Reorder(ctx context.Context, typeName string, req recordapi.ReorderRequest) error {
140		if err := w.live(); err != nil {
141			return err
142		}
143		return w.rs.Reorder(ctx, typeName, req)
144	}
145	
146	func (w *Writer) Push(ctx context.Context, typeName, id, field, value string) error {
147		if err := w.live(); err != nil {
148			return err
149		}
150		_, err := w.rs.PushListEntry(ctx, typeName, id, field, value)
151		return err
152	}
153	
154	func (w *Writer) Fold(ctx context.Context, typeName, id, field string, remove []string, value string) error {
155		if err := w.live(); err != nil {
156			return err
157		}
158		_, err := w.rs.FoldListEntries(ctx, typeName, id, field, remove, value)
159		return err
160	}
161	
162	func (w *Writer) live() error {
163		select {
164		case <-w.fenced:
165			return ErrFenced
166		default:
167			return nil
168		}
169	}
170	
171	// Publish pushes what Apply, Reorder, Push and Fold committed, which they leave
172	// local so a burst shares one push. A failed push is logged rather than returned:
173	// strata keeps the commits queued for the next push, and an error would invite
174	// the caller to write twice.
175	func (w *Writer) Publish(ctx context.Context) {
176		if err := w.s.Push(origin); err != nil {
177			slog.WarnContext(ctx, "stratawrite: publishing deferred to the next push",
178				slog.String("store", w.store), slog.String("writer", w.ID()), slog.Any("error", err))
179		}
180	}
181	
182	// Tick catches up with other writers, lifts this writer's low-water mark if it
183	// holds the barrier, then runs the same maintenance as Start.
184	func (w *Writer) Tick(ctx context.Context) error {
185		if err := w.live(); err != nil {
186			return err
187		}
188		if err := w.s.Fetch(origin); err != nil {
189			return fmt.Errorf("stratawrite: fetching %s: %w", w.store, err)
190		}
191		if _, err := w.s.Lift(); err != nil {
192			return fmt.Errorf("stratawrite: lifting %s: %w", w.ID(), err)
193		}
194		return w.maintain(ctx)
195	}
196	
197	// End evicts this writer, publishes, then releases its lease. Only a leased
198	// writer can be evicted by another session, so the lease goes last.
199	func (w *Writer) End(ctx context.Context) error {
200		// The transport doesn't use ctx, so ctx ending cuts it instead.
201		stop := context.AfterFunc(ctx, w.close)
202		defer stop()
203		w.stopRenew()
204		<-w.done
205		defer w.close()
206		// An eviction another session already published is adopted on push.
207		if err := w.s.Evict(w.ID()); err != nil {
208			return fmt.Errorf("evicting self: %w", err)
209		}
210		if err := w.s.Push(origin); err != nil {
211			return fmt.Errorf("publishing: %w", err)
212		}
213		return w.release(ctx, w.ID())
214	}
215	
216	// Abort cuts the writer's transport for good, End included, so its lease lapses.
217	// Unlike the rest of Writer, any goroutine may call it, more than once, and
218	// while End runs.
219	func (w *Writer) Abort() { w.close() }
220	
221	// maintain evicts writers whose leases lapsed, folds, then retires the evicted
222	// writers the fold covers, best-effort. A writer the fold doesn't cover yet
223	// (ErrNotFolded) is left for a later session. Evicted writers' leases go only
224	// once the evictions are published, as in End.
225	func (w *Writer) maintain(ctx context.Context) error {
226		var errs []error
227		evicted, err := w.evictLapsed(ctx)
228		if err != nil {
229			errs = append(errs, err)
230		}
231		if err := w.evictStaleBlocker(ctx); err != nil {
232			errs = append(errs, err)
233		}
234		if _, err := w.s.Compact(); err != nil {
235			errs = append(errs, fmt.Errorf("compacting: %w", err))
236		}
237		if err := w.retireEvicted(); err != nil {
238			errs = append(errs, err)
239		}
240		if _, err := w.s.RetainGenerations(); err != nil {
241			errs = append(errs, fmt.Errorf("retaining generations: %w", err))
242		}
243		if err := w.s.Push(origin); err != nil {
244			errs = append(errs, fmt.Errorf("publishing: %w", err))
245		} else if len(evicted) > 0 {
246			errs = append(errs, w.release(ctx, evicted...))
247		}
248		return errors.Join(errs...)
249	}
250	
251	func (w *Writer) evictLapsed(ctx context.Context) ([]string, error) {
252		lapsed, err := w.leases.LapsedStrataWriters(ctx, w.repoID, w.store, w.evict)
253		if err != nil {
254			return nil, err
255		}
256		if len(lapsed) == 0 {
257			return nil, nil
258		}
259		// A lapsed writer may already be evicted, by an End that published and then
260		// failed to release. Evicting it again would queue an eviction the remote
261		// refuses, failing every later push.
262		already, err := w.s.EvictedWriters()
263		if err != nil {
264			return nil, err
265		}
266		var evicted []string
267		var errs []error
268		for _, other := range lapsed {
269			if other == w.ID() {
270				continue
271			}
272			if slices.Contains(already, other) {
273				evicted = append(evicted, other)
274				continue
275			}
276			if err := w.s.Evict(other); err != nil {
277				errs = append(errs, fmt.Errorf("evicting lapsed %s: %w", other, err))
278				continue
279			}
280			evicted = append(evicted, other)
281		}
282		return evicted, errors.Join(errs...)
283	}
284	
285	// evictStaleBlocker leaves a writer that never wrote: it has no age to judge.
286	func (w *Writer) evictStaleBlocker(ctx context.Context) error {
287		r, err := w.s.Status()
288		if err != nil {
289			return fmt.Errorf("surveying %s: %w", w.store, err)
290		}
291		if r.Blocking == "" || r.Blocking == w.ID() || r.BlockingSince.IsZero() ||
292			time.Since(r.BlockingSince) < w.staleBlocker {
293			return nil
294		}
295		leased, err := w.leases.HasStrataLease(ctx, w.repoID, w.store, r.Blocking)
296		if err != nil || leased {
297			return err
298		}
299		slog.WarnContext(ctx, "stratawrite: evicting a writer with no lease that has held the barrier since it last wrote",
300			slog.String("store", w.store), slog.String("writer", r.Blocking),
301			slog.Time("last_wrote", r.BlockingSince), slog.Uint64("barrier", r.Barrier))
302		// Blocking is drawn only from writers not yet evicted, so this never
303		// repeats an eviction the remote would refuse.
304		if err := w.s.Evict(r.Blocking); err != nil {
305			return fmt.Errorf("evicting stale %s: %w", r.Blocking, err)
306		}
307		return nil
308	}
309	
310	func (w *Writer) retireEvicted() error {
311		evicted, err := w.s.EvictedWriters()
312		if err != nil {
313			return err
314		}
315		for _, other := range evicted {
316			if other == w.ID() {
317				continue
318			}
319			if _, err := w.s.Retire(other); err != nil && !errors.Is(err, strata.ErrNotFolded) {
320				return fmt.Errorf("retiring %s: %w", other, err)
321			}
322		}
323		return nil
324	}
325	
326	func (w *Writer) release(ctx context.Context, writers ...string) error {
327		return w.leases.ReleaseStrataLeases(ctx, w.repoID, w.store, writers)
328	}
329	
330	// renew fences the writer once the lease is gone or renewing has failed for
331	// half the eviction window.
332	func (w *Writer) renew(ctx context.Context) {
333		defer close(w.done)
334		t := time.NewTicker(w.evict / 4)
335		defer t.Stop()
336		lastOK := time.Now()
337		for {
338			select {
339			case <-ctx.Done():
340				return
341			case <-t.C:
342			}
343			// Bounded so a renewal stuck on the database can't outlast the fence.
344			rctx, cancel := context.WithDeadline(ctx, lastOK.Add(w.evict/2))
345			ok, err := w.leases.RenewStrataLease(rctx, w.repoID, w.store, w.ID())
346			cancel()
347			if ctx.Err() != nil {
348				return
349			}
350			why := ""
351			switch {
352			case err == nil && ok:
353				lastOK = time.Now()
354			case err == nil:
355				why = "lease is gone"
356			case time.Since(lastOK) >= w.evict/2:
357				why = err.Error()
358			}
359			if why != "" {
360				slog.WarnContext(ctx, "stratawrite: writer fenced",
361					slog.String("store", w.store), slog.String("writer", w.ID()), slog.String("why", why))
362				close(w.fenced)
363				return
364			}
365		}
366	}
