1	// Package stratawrite writes entire-records stores held in strata, over git to
2	// entiredb. Each call writes into a fresh in-memory clone that is dropped
3	// afterwards, as a one-shot writer that never holds a store's compaction back.
4	package stratawrite
5	
6	import (
7		"context"
8		"errors"
9		"fmt"
10	
11		"github.com/entirehq/entire-records/recordapi"
12		"github.com/entirehq/entire-records/schema"
13		recstore "github.com/entirehq/entire-records/store"
14		"github.com/entirehq/strata/git"
15		strata "github.com/entirehq/strata/store"
16	
17		"github.com/entirehq/entire-api/internal/stratagit"
18	)
19	
20	// Remote is one repository's git endpoint, reached as one caller.
21	type Remote stratagit.Remote
22	
23	const origin = stratagit.Origin
24	
25	func (r Remote) open(ctx context.Context, store string) (*strata.Store, error) {
26		return stratagit.Remote(r).Open(ctx, store)
27	}
28	
29	// Create creates a store with its schema, or updates an existing one's. It is
30	// safe to retry, even after ErrUnconfirmed: applying the schema a store already
31	// has writes nothing.
32	func (r Remote) Create(ctx context.Context, desired schema.Schema, author string) error {
33		s, err := r.open(ctx, desired.Name)
34		if err != nil {
35			return err
36		}
37		e := recstore.OpenStore(s, recstore.SchemaRef{Name: desired.Name}, author, true)
38		if _, err := e.PlanSchemaChange(desired, recstore.ApplyOptions{}); err != nil {
39			return fmt.Errorf("%w: %w", ErrSchemaRefused, err)
40		}
41		if _, err := e.ApplySchema(ctx, desired, recstore.ApplyOptions{}); err != nil {
42			return err
43		}
44		if err := publish(s); err != nil {
45			return fmt.Errorf("stratawrite: publishing %s: %w", desired.Name, err)
46		}
47		return nil
48	}
49	
50	// ErrSchemaRefused is a valid schema the store won't take against what it
51	// already holds.
52	var ErrSchemaRefused = errors.New("stratawrite: the store refuses this schema")
53	
54	// OneShot applies one batch to an existing store as one commit and publishes
55	// it. A store nobody created fails with store.ErrNoSchema. On ErrUnconfirmed it
56	// still returns what it wrote, so the caller can look for it.
57	func (r Remote) OneShot(ctx context.Context, store string, b recordapi.Batch, author string) ([]recordapi.RecordRef, error) {
58		s, err := r.open(ctx, store)
59		if err != nil {
60			return nil, err
61		}
62		e := recstore.OpenStore(s, recstore.SchemaRef{Name: store}, author, true)
63		if len(b.Writes) == 0 && len(b.Deletes) == 0 {
64			if err := requireSchema(e, store); err != nil {
65				return nil, err
66			}
67			return nil, nil
68		}
69		written, err := recordapi.New(e).ApplyBatch(ctx, b, "")
70		if err != nil {
71			if noSchema := requireSchema(e, store); errors.Is(noSchema, recstore.ErrNoSchema) {
72				return nil, noSchema
73			}
74			return nil, err
75		}
76		if err := publish(s); err != nil {
77			err = fmt.Errorf("stratawrite: publishing %s: %w", store, err)
78			if errors.Is(err, ErrUnconfirmed) {
79				return written, err
80			}
81			return nil, err
82		}
83		return written, nil
84	}
85	
86	// ErrUnconfirmed is a publish that may have landed with its answer lost. A
87	// retry could land a batch with minted IDs twice.
88	var ErrUnconfirmed = errors.New("stratawrite: the write may or may not have landed")
89	
90	// publish retries an unrefused push once; create-only refs make that idempotent.
91	func publish(s *strata.Store) error {
92		err := s.Push(origin)
93		if err == nil || errors.Is(err, git.ErrRejected) {
94			return err
95		}
96		again := s.Push(origin)
97		switch {
98		case again == nil:
99			return nil
100		case errors.Is(again, git.ErrRejected):
101			// Had the first push landed, the retry would have found its refs.
102			return again
103		}
104		return fmt.Errorf("%w: %w", ErrUnconfirmed, err)
105	}
106	
107	func requireSchema(e *recstore.Engine, store string) error {
108		sch, err := e.LoadSchema()
109		if err != nil {
110			return err
111		}
112		if len(sch.Types) == 0 {
113			return fmt.Errorf("%s: %w", store, recstore.ErrNoSchema)
114		}
115		return nil
116	}
