1	package stratagit
2	
3	import (
4		"fmt"
5		"strings"
6	
7		"github.com/entirehq/strata/git"
8		"github.com/go-git/go-git/v6/plumbing"
9	)
10	
11	// Refs are a map under Repo.mu rather than go-git's reference store, which
12	// strata's ADR-0001 rejected for lacking create-if-absent and atomic multi-ref
13	// updates.
14	
15	func (r *Repo) Ref(ref string) (string, error) {
16		r.mu.RLock()
17		defer r.mu.RUnlock()
18		return r.refs[ref], nil
19	}
20	
21	func (r *Repo) Refs(prefix string) (map[string]string, error) {
22		r.mu.RLock()
23		defer r.mu.RUnlock()
24		p := git.Prefix(prefix)
25		out := map[string]string{}
26		for name, oid := range r.refs {
27			if under(p, name) {
28				out[name] = oid
29			}
30		}
31		return out, nil
32	}
33	
34	// under matches at a path component, so "refs/a" holds "refs/a/b" but not
35	// "refs/ab". Refs and LsRemote share it so they agree.
36	func under(prefix, ref string) bool {
37		return prefix == "" || ref == prefix || strings.HasPrefix(ref, prefix+"/")
38	}
39	
40	func (r *Repo) SetRef(ref, newOID, oldOID string) error {
41		return r.ApplyRefOps([]git.RefOp{{
42			Kind: kindFor(newOID, oldOID), Ref: ref, New: newOID, Old: oldOID,
43		}})
44	}
45	
46	func kindFor(newOID, oldOID string) git.RefKind {
47		switch {
48		case newOID == "":
49			return git.RefDelete
50		case oldOID == "":
51			return git.RefCreate
52		default:
53			return git.RefUpdate
54		}
55	}
56	
57	// ApplyRefOps checks every op against the refs as they were on entry, then
58	// writes them all, so a batch lands whole or not at all. The write pass must not
59	// re-check: it could then fail with the batch half applied.
60	func (r *Repo) ApplyRefOps(ops []git.RefOp) error {
61		r.mu.Lock()
62		defer r.mu.Unlock()
63	
64		for _, op := range ops {
65			if err := r.check(op); err != nil {
66				return err
67			}
68		}
69		for _, op := range ops {
70			if op.Kind == git.RefDelete {
71				delete(r.refs, op.Ref)
72				continue
73			}
74			r.refs[op.Ref] = op.New
75		}
76		return nil
77	}
78	
79	// check: the caller holds mu.
80	func (r *Repo) check(op git.RefOp) error {
81		have, exists := r.refs[op.Ref]
82		switch op.Kind {
83		case git.RefCreate:
84			if exists {
85				return fmt.Errorf("stratagit: %s exists: %w", op.Ref, git.ErrRefChanged)
86			}
87		case git.RefUpdate:
88			if !exists {
89				return fmt.Errorf("stratagit: %s does not exist: %w", op.Ref, git.ErrRefChanged)
90			}
91			if have != op.Old {
92				return fmt.Errorf("stratagit: %s holds %q, not %q: %w",
93					op.Ref, have, op.Old, git.ErrRefChanged)
94			}
95		case git.RefDelete:
96			// An empty Old deletes whatever is there, as update-ref does.
97			if op.Old != "" && !exists {
98				return fmt.Errorf("stratagit: %s does not exist: %w", op.Ref, git.ErrRefChanged)
99			}
100			if op.Old != "" && have != op.Old {
101				return fmt.Errorf("stratagit: %s holds %q, not %q: %w",
102					op.Ref, have, op.Old, git.ErrRefChanged)
103			}
104		default:
105			return fmt.Errorf("stratagit: %s has no ref operation kind", op.Ref)
106		}
107		return nil
108	}
109	
110	func (r *Repo) CheckRefFormat(ref string) error {
111		if err := plumbing.ReferenceName(ref).Validate(); err != nil {
112			return fmt.Errorf("stratagit: %q: %w", ref, git.ErrBadRefName)
113		}
114		return nil
115	}
