139	// report adds a record as gone, whole, or patched. One the caller may not have
140	// held -- no visible field predates the token, or its floor rose -- goes whole.
141	func (o opened) report(out *ChangesResult, t touchedRecord) error {
142		rt, ok := o.schema.Type(t.ref.Type)
143		if !ok {
144			out.Deleted = append(out.Deleted, t.ref)
145			return nil
146		}
