150			return nil
151		}
152		if t.changed.FloorWriter != "" || !t.changed.Held {
153			rec, err := o.store.GetRecord(rt, addr)
154			if errors.Is(err, recstore.ErrNotFound) {
155				out.Deleted = append(out.Deleted, t.ref)
156				return nil
157			}
158			if err != nil {
159				return err
160			}
161			out.Records = append(out.Records, recordapi.ShapeRecords(rt, []*recstore.Record{rec})[0])
162			return nil
163		}
