223	// with this one's by chance. It guards against a mix-up, not a forgery.
224	func changesKey(repoID string, ref recstore.SchemaRef) string {
225		sum := sha256.Sum256([]byte(repoID + "\x00" + ref.String()))
226		return hex.EncodeToString(sum[:])[:10]
227	}
