240		p, err := parseChangesToken(token)
241		if err != nil {
242			return changesPosition{}, err
243		}
244		ref, err := parseSchemaAddress(address)
245		if err != nil {
246			return changesPosition{}, err
247		}
248		if p.Key != changesKey(repoID, ref) {
249			return changesPosition{}, fmt.Errorf("%w: changes token: issued for another repository or store", recstore.ErrInvalid)
250		}
251		return p, nil
252	}
253	
254	func parseChangesToken(token string) (changesPosition, error) {
255		if token == "" || len(token) > maxChangesTokenLen {
256			return changesPosition{}, fmt.Errorf("%w: changes token: missing or too long", recstore.ErrInvalid)
257		}
258		p, err := decodeToken[changesPosition](token)
259		if err != nil {
260			return changesPosition{}, fmt.Errorf("%w: changes token: not one this service issued", recstore.ErrInvalid)
261		}
262		return p, nil
263	}
