package records

import (
	"context"
	"crypto/sha256"
	"encoding/hex"
	"errors"
	"fmt"
	"slices"
	"strings"

	"github.com/entirehq/entire-records/recordapi"
	recstore "github.com/entirehq/entire-records/store"

	"github.com/entirehq/entire-api/internal/recordchange"
)

// ChangesResult is what a store did after the state a changes token names.
// Patches are for records the caller holds; Records are the rest, whole.
type ChangesResult struct {
	Tip     string
	Token   string
	Patches []RecordPatch
	Records []recordDTO
	Deleted []recordapi.RecordRef
	// Reload: the change can't be told as records (new generation, schema
	// version, expiry or erasure). The caller reads the store whole again.
	Reload bool
}

func (c ChangesResult) Empty() bool {
	return !c.Reload && len(c.Patches)+len(c.Records)+len(c.Deleted) == 0
}

// ChangesOptions narrow a changes read. No Types means every type. Records only
// the writer named by Except touched are left out.
type ChangesOptions struct {
	Types  []string
	Except string
}

// RecordPatch is what changed in a record the caller holds. Set holds whole
// field values; Append holds entries pushed at a list's end, with the list's new
// length for the caller to check its own against. Label, ParentID and Rank are
// always restated.
type RecordPatch struct {
	Type     string                `json:"type"`
	ID       string                `json:"id"`
	Label    string                `json:"label"`
	ParentID string                `json:"parentId,omitempty"`
	Rank     string                `json:"rank,omitempty"`
	Set      map[string]any        `json:"set,omitempty"`
	Append   map[string]ListAppend `json:"append,omitempty"`
}

type ListAppend struct {
	Values []string `json:"values"`
	Length int      `json:"length"`
}

// Changes reads what a store did after the state token names, as the records
// now stand.
func (r *Reader) Changes(ctx context.Context, repoID, address, token string, opts ChangesOptions) (ChangesResult, error) {
	since, err := parseChangesTokenFor(token, repoID, address)
	if err != nil {
		return ChangesResult{}, err
	}
	o, err := r.open(ctx, repoID, address)
	if err != nil {
		return ChangesResult{}, err
	}
	defer o.Release()
	types, err := distinctDeclaredTypes(o.schema, opts.Types)
	if err != nil {
		return ChangesResult{}, err
	}
	out := ChangesResult{Tip: o.At.Tip, Token: o.changesToken()}
	now := o.position()
	// Rows can only tell changes within one generation, schema version and
	// removal set; a tick behind the token means the projection was rebuilt.
	at := now
	at.Tick = since.Tick
	if at != since || since.Tick > now.Tick {
		out.Reload = true
		return out, nil
	}
	if since.Tick == now.Tick {
		return out, nil
	}
	changed, err := o.ChangedSince(since.Tick)
	if err != nil {
		return ChangesResult{}, err
	}
	for _, t := range touched(changed, types, opts.Except) {
		if err := o.report(&out, t); err != nil {
			return ChangesResult{}, err
		}
	}
	return out, nil
}

type touchedRecord struct {
	ref     recordapi.RecordRef
	changed recordchange.Record
}

// touched leaves out rows no record owns (schema storage, bookkeeping): a schema
// change reaches the caller as a reload instead.
func touched(changed []recordchange.Record, types []string, except string) []touchedRecord {
	var out []touchedRecord
	for _, c := range changed {
		typeName, addr, _, ok := recstore.RecordOfOp(c.Key.Type, c.Key.ID, "")
		if !ok || (len(types) > 0 && !slices.Contains(types, typeName)) || (except != "" && onlyBy(c, except)) {
			continue
		}
		out = append(out, touchedRecord{ref: recordapi.RecordRef{Type: typeName, ID: addr.String()}, changed: c})
	}
	slices.SortFunc(out, func(a, b touchedRecord) int {
		if c := strings.Compare(a.ref.Type, b.ref.Type); c != 0 {
			return c
		}
		return strings.Compare(a.ref.ID, b.ref.ID)
	})
	return out
}

func onlyBy(c recordchange.Record, writer string) bool {
	if c.FloorWriter != "" && c.FloorWriter != writer {
		return false
	}
	for _, f := range c.Fields {
		if f.Writer != writer {
			return false
		}
	}
	return true
}

// report adds a record as gone, whole, or patched. One the caller may not have
// held -- no visible field predates the token, or its floor rose -- goes whole.
func (o opened) report(out *ChangesResult, t touchedRecord) error {
	rt, ok := o.schema.Type(t.ref.Type)
	if !ok {
		out.Deleted = append(out.Deleted, t.ref)
		return nil
	}
	addr, err := recstore.ParseAddress(t.ref.ID)
	if err != nil {
		out.Deleted = append(out.Deleted, t.ref)
		return nil
	}
	if t.changed.FloorWriter != "" || !t.changed.Held {
		rec, err := o.store.GetRecord(rt, addr)
		if errors.Is(err, recstore.ErrNotFound) {
			out.Deleted = append(out.Deleted, t.ref)
			return nil
		}
		if err != nil {
			return err
		}
		out.Records = append(out.Records, recordapi.ShapeRecords(rt, []*recstore.Record{rec})[0])
		return nil
	}
	fields := make([]recstore.FieldChange, len(t.changed.Fields))
	for i, f := range t.changed.Fields {
		fields[i] = recstore.FieldChange{Field: f.Field, Value: f.Value, Unbound: f.Deleted}
	}
	change, err := o.store.GetRecordChange(rt, addr, fields)
	if errors.Is(err, recstore.ErrNotFound) {
		out.Deleted = append(out.Deleted, t.ref)
		return nil
	}
	if err != nil {
		return err
	}
	out.Patches = append(out.Patches, patchOf(recordapi.ShapeRecords(rt, []*recstore.Record{change.Record})[0], change))
	return nil
}

func patchOf(dto recordDTO, change recstore.RecordChange) RecordPatch {
	p := RecordPatch{Type: dto.Type, ID: dto.ID, Label: dto.Label, ParentID: dto.ParentID, Rank: dto.Rank}
	for _, key := range change.Changed {
		if values, ok := change.Appended[key]; ok {
			if p.Append == nil {
				p.Append = map[string]ListAppend{}
			}
			p.Append[key] = ListAppend{Values: values, Length: len(recordapi.MultiValueField(dto, key))}
			continue
		}
		if p.Set == nil {
			p.Set = map[string]any{}
		}
		p.Set[key] = dto.Fields[key]
	}
	return p
}

// StoreOf names the strata store a schema address reads.
func StoreOf(address string) (string, error) {
	ref, err := parseSchemaAddress(address)
	if err != nil {
		return "", err
	}
	return ref.Name, nil
}

// changesPosition is a changes token's content. Short keys: it travels in
// Last-Event-ID.
type changesPosition struct {
	Key        string `json:"k"`
	Generation uint64 `json:"g"`
	Tick       uint64 `json:"t"`
	Schema     int    `json:"s"`
	Removals   string `json:"r"`
}

func (o opened) position() changesPosition {
	return changesPosition{Key: o.key, Generation: o.At.Generation, Tick: o.At.Tick, Schema: o.schema.Version,
		Removals: o.At.Removals}
}

// changesKey ties a token to its store: another store's numbers could line up
// with this one's by chance. It guards against a mix-up, not a forgery.
func changesKey(repoID string, ref recstore.SchemaRef) string {
	sum := sha256.Sum256([]byte(repoID + "\x00" + ref.String()))
	return hex.EncodeToString(sum[:])[:10]
}

func (o opened) changesToken() string { return encodeToken(o.position()) }

const maxChangesTokenLen = 256

// ValidChangesToken refuses a token not issued for this store.
func ValidChangesToken(token, repoID, address string) error {
	_, err := parseChangesTokenFor(token, repoID, address)
	return err
}

func parseChangesTokenFor(token, repoID, address string) (changesPosition, error) {
	p, err := parseChangesToken(token)
	if err != nil {
		return changesPosition{}, err
	}
	ref, err := parseSchemaAddress(address)
	if err != nil {
		return changesPosition{}, err
	}
	if p.Key != changesKey(repoID, ref) {
		return changesPosition{}, fmt.Errorf("%w: changes token: issued for another repository or store", recstore.ErrInvalid)
	}
	return p, nil
}

func parseChangesToken(token string) (changesPosition, error) {
	if token == "" || len(token) > maxChangesTokenLen {
		return changesPosition{}, fmt.Errorf("%w: changes token: missing or too long", recstore.ErrInvalid)
	}
	p, err := decodeToken[changesPosition](token)
	if err != nil {
		return changesPosition{}, fmt.Errorf("%w: changes token: not one this service issued", recstore.ErrInvalid)
	}
	return p, nil
}

package recordprojection

import (
	"context"
	"crypto/sha256"
	"encoding/binary"
	"encoding/hex"
	"fmt"
	"hash"
	"log/slog"
	"slices"
	"strings"

	"github.com/entirehq/strata/erasure"
	"github.com/entirehq/strata/project"
	"github.com/entirehq/strata/reflayout"
	strata "github.com/entirehq/strata/store"
	"go.opentelemetry.io/otel/attribute"
	"go.opentelemetry.io/otel/trace"

	"github.com/entirehq/entire-api/internal/records"
	"github.com/entirehq/entire-api/internal/store"
	"github.com/entirehq/entire-api/internal/stratagit"
)

// Reads is records.Source over this cell's Postgres projection. Every read
// fetches over git, as the caller, what the store holds past where the last
// read stopped, and ticks the projection; nothing else advances it. Concurrent
// reads of one store queue on the tick's lock.
type Reads struct {
	Store *store.RepoStore
	// Remote is routed as a strata push is, so a read sees the caller's own
	// landed writes.
	Remote func(ctx context.Context, repoID string) stratagit.Remote
}

func (p Reads) Open(ctx context.Context, repoID, name string) (records.Opened, error) {
	proj, err := p.Store.RecordProjectionFor(repoID, name)
	if err != nil {
		return records.Opened{}, fmt.Errorf("recordprojection: projection for %s/%s: %w", repoID, name, err)
	}
	var read stratagit.Read
	view, release, res, err := proj.TickAndRead(ctx, fetching{ctx: ctx, remote: p.Remote(ctx, repoID), name: name, read: &read})
	if err != nil {
		return records.Opened{}, fmt.Errorf("recordprojection: ticking %s/%s: %w", repoID, name, err)
	}
	trace.SpanFromContext(ctx).SetAttributes(
		attribute.String("records.read", read.String()),
		attribute.Int64("records.lock_wait_ms", res.LockWait.Milliseconds()),
		attribute.Int("records.writers_written", res.WritersWritten),
		attribute.Int("records.writers_dropped", res.WritersDropped),
		attribute.Int("records.fields_written", res.FieldsWritten))
	if res.Seeded > 0 || res.Ops > 0 {
		slog.InfoContext(ctx, "record projection advanced",
			slog.String("repo_id", repoID),
			slog.String("store", name),
			slog.Uint64("generation", res.Cursor.Generation),
			slog.Int("seeded", res.Seeded),
			slog.Int("ops", res.Ops))
	}
	return records.Opened{
		Projection: view,
		At: records.State{
			Tip:        stateTip(res.Cursor, res.Erased),
			Generation: res.Cursor.Generation,
			Tick:       res.Tick,
			Removals:   removals(res.Expired, res.Erased),
		},
		ChangedSince: view.ChangedSince,
		Release:      release,
	}, nil
}

// removals digests a store's expiry cutoffs and erasures. Short, because it
// travels in a changes token; a collision costs one missed reload.
func removals(expired []project.Expiry, erased []erasure.Erasure) string {
	h := sha256.New()
	var n [8]byte
	cutoffs := slices.Clone(expired)
	slices.SortFunc(cutoffs, func(a, b project.Expiry) int { return strings.Compare(a.Type, b.Type) })
	for _, e := range cutoffs {
		binary.BigEndian.PutUint64(n[:], uint64(len(e.Type)))
		h.Write(n[:])
		h.Write([]byte(e.Type))
		binary.BigEndian.PutUint64(n[:], e.Below)
		h.Write(n[:])
	}
	h.Write([]byte{0xff})
	hashErasures(h, erased)
	return hex.EncodeToString(h.Sum(nil))[:16]
}

// hashErasures is the one encoding of an erasure set, shared by the tip and the
// changes token. Fields are length-prefixed: they are free text.
func hashErasures(h hash.Hash, erased []erasure.Erasure) {
	var n [8]byte
	for _, e := range erasure.Canonical(erased) {
		binary.BigEndian.PutUint64(n[:], uint64(e.Kind))
		h.Write(n[:])
		for _, part := range []string{e.Type, e.ID, e.Field, e.Partition} {
			binary.BigEndian.PutUint64(n[:], uint64(len(part)))
			h.Write(n[:])
			h.Write([]byte(part))
		}
		binary.BigEndian.PutUint64(n[:], e.Below)
		h.Write(n[:])
	}
}

// fetching fetches inside Feed, which runs under the projection's lock. A store
// fetched before the lock may predate an erasure another read applied while
// this one waited, and its feed would put the erased ops back.
//
// Each read builds its own in-memory clone and fetches into it only what is
// newer than where the last tick stopped; it holds no connection or goroutine,
// so it needs no closing.
type fetching struct {
	ctx    context.Context
	remote stratagit.Remote
	name   string
	// read is how the tick's read reached the store, for its span.
	read *stratagit.Read
}

var _ store.Resumable = fetching{}

func (f fetching) Feed(c project.Cursor) (project.Batch, error) {
	b, _, _, err := f.FeedSince(c, strata.Since{})
	return b, err
}

func (f fetching) FeedSince(c project.Cursor, since strata.Since) (project.Batch, strata.Since, bool, error) {
	b, next, read, err := f.remote.FeedSince(f.ctx, f.name, c, since)
	if f.read != nil {
		*f.read = read
	}
	if err != nil {
		return project.Batch{}, strata.Since{}, false, fmt.Errorf("recordprojection: reading %s: %w", f.name, err)
	}
	return b, next, read == stratagit.ReadUnmoved, nil
}

// Stores names the repo's record stores from their refs. Sorted and unique.
func (p Reads) Stores(ctx context.Context, repoID string) ([]string, error) {
	refs, err := p.Remote(ctx, repoID).Refs(ctx, "refs/strata")
	if err != nil {
		return nil, fmt.Errorf("recordprojection: listing strata refs: %w", err)
	}
	var names []string
	for ref := range refs {
		if name, ok := storeOf(ref); ok {
			names = append(names, name)
		}
	}
	slices.Sort(names)
	return slices.Compact(names), nil
}

// storeOf names the store a ref belongs to. Refs tracking a remote are not a
// store of this repo's.
func storeOf(ref string) (string, bool) {
	r := reflayout.Parse(ref)
	switch {
	case r.Store == "", r.Remote != "":
		return "", false
	case r.Kind == reflayout.Unknown, r.Kind == reflayout.Unnumbered:
		return "", false
	}
	return r.Store, true
}

// stateTip hashes a projection's state to a commit id's width. It covers the
// erasure set as well as the cursor, since an erasure removes records without
// moving the cursor.
func stateTip(c project.Cursor, erased []erasure.Erasure) string {
	h := sha256.New()
	var n [8]byte
	binary.BigEndian.PutUint64(n[:], c.Generation)
	h.Write(n[:])
	writers := make([]string, 0, len(c.Writers))
	for w := range c.Writers {
		writers = append(writers, w)
	}
	slices.Sort(writers)
	for _, w := range writers {
		h.Write([]byte(w))
		h.Write([]byte{0})
		binary.BigEndian.PutUint64(n[:], c.Writers[w])
		h.Write(n[:])
	}
	hashErasures(h, erased)
	return hex.EncodeToString(h.Sum(nil))[:40]
}

// Package recordchange is the shape of a projection's changed rows, shared by
// internal/store and internal/records.
package recordchange

import "github.com/entirehq/strata/record"

// Record is one record a later tick wrote. Key is the strata key, not the records address.
type Record struct {
	Key    record.Key
	Fields []Field
	// FloorWriter is set when the record's delete floor rose since, by that writer.
	FloorWriter string
	// Held: a visible field predates the asked tick. Meaningless when the floor rose.
	Held bool
}

// Field is a field row as it now stands; Writer decided it.
type Field struct {
	Field   string
	Value   []byte
	Deleted bool
	Writer  string
}

// Package refstream subscribes to entiredb's live repo_refs_v1 ref-change
// stream over a plain core NATS subscription — not a JetStream durable
// consumer (go-nuts's jsconsumer package requires a non-empty Durable, and a
// per-connection durable consumer would be real per-viewer NATS server
// state; see internal/ingest/pipeline.go for the durable-consumer side this
// deliberately does NOT reuse). One subscription serves every local viewer of
// a repo: the caller (internal/httpapi's live ref-events SSE hub) shares one
// Subscribe call per watched repo_id across all of that repo's open
// connections, mirroring the ref-counted "one poll, not N" pattern the
// DB-polling SSE hubs already use for reviews/threads — here push- rather
// than poll-driven.
//
// Delivery is at-most-once (core NATS: no ack, no replay, no durable
// server-side state) — the right contract for a live "this ref just changed"
// signal, where a client re-establishes current state on every reconnect
// rather than replaying missed history.
package refstream

import (
	"context"
	"fmt"
	"log/slog"

	"github.com/nats-io/nats.go"

	"github.com/entirehq/entire-api/internal/ingest"
)

// refEventSubjectPrefix is the entiredb-published ref-change subject this
// package subscribes to, scoped to one repo per Subscribe call
// (repo_refs_v1.{repo_id}) — the same subject internal/ingest's durable
// JetStream consumer reads in the repo-activity worker.
const refEventSubjectPrefix = "repo_refs_v1."

// subscribeBuffer bounds how many parsed-but-undelivered RefEvents the
// returned channel holds before a stalled reader causes new events to be
// dropped rather than blocking the NATS client's shared delivery goroutine.
// Sized generously — the caller (the hub) drains the channel promptly — as a
// guard against a stall on one repo's channel propagating into the whole
// connection's message dispatch, not a depth reached in normal operation.
const subscribeBuffer = 64

// Subscribe opens a core (non-JetStream) NATS subscription to repoID's live
// ref-change subject and returns a channel of parsed events plus an unsubscribe
// func. ctx is used only to attribute the async log lines a slow/malformed
// message can produce — it does NOT bound the subscription's lifetime; unsub
// is the sole teardown path, called once by the caller (the hub) when the last
// local viewer of repoID disconnects. The returned channel is never closed
// (closing it here would race the NATS client's own delivery goroutine, which
// keeps invoking the callback until Unsubscribe has fully taken effect) — a
// caller must stop reading from it via its own lifecycle (e.g. a
// ctx.Done()-gated select), not by observing the channel close.
func Subscribe(ctx context.Context, nc *nats.Conn, repoID string) (<-chan ingest.RefEvent, func(), error) {
	if repoID == "" {
		return nil, nil, fmt.Errorf("refstream: repoID is empty")
	}
	logCtx := context.WithoutCancel(ctx)
	ch := make(chan ingest.RefEvent, subscribeBuffer)
	sub, err := nc.Subscribe(refEventSubjectPrefix+repoID, func(msg *nats.Msg) {
		ev, err := ingest.ParseRefEvent(msg.Data)
		if err != nil {
			slog.WarnContext(logCtx, "refstream: dropping unparseable ref event",
				slog.String("repo_id", repoID), slog.Any("error", err))
			return
		}
		select {
		case ch <- ev:
		default:
			// A stalled reader would otherwise block this subject's NATS delivery
			// goroutine. Dropping here is the same at-most-once, gaps-are-fine
			// contract as a message never arriving at all — the next SSE
			// reconnect re-snapshots current state regardless.
			slog.WarnContext(logCtx, "refstream: subscriber buffer full, dropping ref event",
				slog.String("repo_id", repoID), slog.String("ref_name", ev.RefName))
		}
	})
	if err != nil {
		return nil, nil, fmt.Errorf("refstream: subscribe %s: %w", repoID, err)
	}
	return ch, func() { _ = sub.Unsubscribe() }, nil
}

// Reconnected receives each time nc comes back from a disconnect. Delivery is
// at-most-once, so a holder of state re-reads it then. stop ends the watch.
func Reconnected(nc *nats.Conn) (reconnected <-chan nats.Status, stop func()) {
	ch := nc.StatusChanged(nats.CONNECTED)
	return ch, func() { nc.RemoveStatusListener(ch) }
}

