// It ports strata's internal/gitmem (the driver) and examples/gogit (the
// transport), which strata keeps out of its dependency-free library; strata's
// conformance suites check both. Nothing touches disk, and GitDir names a
// directory that is never created.
package stratagit

import (
	"bytes"
	"errors"
	"fmt"
	"io"
	"sort"
	"strings"
	"sync"
	"time"

	"github.com/entirehq/strata/git"
