	"github.com/go-git/go-git/v6/plumbing/object"
	"github.com/go-git/go-git/v6/storage/memory"
)

// Driver holds in-memory repositories by directory, so two Opens of one
// directory are two handles on one repository, as they are on disk.
type Driver struct {
	mu    sync.Mutex
	repos map[string]*Repo
}

func NewDriver() *Driver { return &Driver{repos: map[string]*Repo{}} }

// Open fails with ErrNotFound for a directory nothing has Init'ed, which is
// what Store.Open relies on to fall back to Init.
func (d *Driver) Open(dir string) (git.Repo, error) {
	d.mu.Lock()
	defer d.mu.Unlock()
	r, ok := d.repos[dir]
	if !ok {
		return nil, fmt.Errorf("stratagit: %s: %w", dir, git.ErrNotFound)
	}
	return r, nil
}

// Init ignores Bare and RefFormat, which nothing here can observe.
func (d *Driver) Init(dir string, opts git.InitOptions) (git.Repo, error) {
	d.mu.Lock()
	defer d.mu.Unlock()
	if r, ok := d.repos[dir]; ok {
		return r, nil
	}
	store := memory.NewStorage()
	switch opts.ObjectFormat {
	case "", "sha1":
		if err := store.SetObjectFormat(config.SHA1); err != nil {
			return nil, fmt.Errorf("stratagit: %w", err)
		}
	case "sha256":
		if err := store.SetObjectFormat(config.SHA256); err != nil {
			return nil, fmt.Errorf("stratagit: %w", err)
		}
	default:
		return nil, fmt.Errorf("stratagit: object format %q is neither sha1 nor sha256",
			opts.ObjectFormat)
	}
	r := &Repo{
		dir:    dir,
		store:  store,
		refs:   map[string]string{},
		config: map[string]string{},
		locks:  map[string]*sync.Mutex{},
		local:  map[string][]byte{},
	}
	d.repos[dir] = r
	return r, nil
}
