package store

import (
	"cmp"
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"hash/fnv"
	"log/slog"
	"maps"
	"slices"
	"strings"
	"sync"
	"time"

	"github.com/jackc/pgx/v5"
	"github.com/jackc/pgx/v5/pgconn"
	"github.com/jackc/pgx/v5/pgxpool"

	"github.com/entirehq/strata/erasure"
	"github.com/entirehq/strata/project"
	"github.com/entirehq/strata/record"
	"github.com/entirehq/strata/reflayout"
	"github.com/entirehq/strata/stamp"
	strata "github.com/entirehq/strata/store"

	"github.com/entirehq/entire-api/internal/recordchange"
)

// RecordProjection is one repo's record store, followed into Postgres.
//
// Each read ticks it from the store's Feed and answers from the rows
// (internal/recordprojection). It is entire-records' examples/sqlproject keyed
// by repo and schema.
type RecordProjection struct {
	s *RepoStore
	// repoID is the ULID's bytes, which is what the ulid domain stores.
	repoID     []byte
	schemaName string
	// ctx is what the two store.Projection reads run under; that interface
	// takes none. See readCtx.
	ctx context.Context
	// q is a TickAndRead view's snapshot; nil reads from the pool.
	q querier
}

// WithContext returns a projection whose reads run under ctx. It must outlive
// every read made through the result: the interface beneath has no room for a
// per-call context.
func (p *RecordProjection) WithContext(ctx context.Context) *RecordProjection {
	out := *p
	out.ctx = ctx
	return &out
}

// recordProjectionLockClass namespaces this feature's advisory locks. The two
// -argument form, because an advisory lock key is global to the database and a
// bare hash would collide with whatever takes one next.
const recordProjectionLockClass = 0x7265_6364 // "recd"

// advisoryUnlockTimeout bounds the release when the tick's own context is gone.
// A var so a test can make the unlock fail and check what happens to the
// connection; nothing else writes it.
var advisoryUnlockTimeout = 5 * time.Second

// lockKey identifies this projection among the class. A hash, so two
// projections collide only by accident of hashing -- which costs them a wait,
// never correctness.
func (p *RecordProjection) lockKey() int32 {
	h := fnv.New32a()
	_, _ = h.Write(p.repoID)
	_, _ = h.Write([]byte{0})
	_, _ = h.Write([]byte(p.schemaName))
	return int32(h.Sum32())
}

// RecordProjectionFor names one projection. Nothing is read or written until a
// method is called.
func (s *RepoStore) RecordProjectionFor(repoID, schemaName string) (*RecordProjection, error) {
	id, err := ulidBytes(repoID)
	if err != nil {
		return nil, fmt.Errorf("store: record projection for %q: %w", repoID, err)
	}
	return &RecordProjection{s: s, repoID: id, schemaName: schemaName}, nil
}

// Feeder is the half of a strata store this needs: somewhere to ask what has
// happened since a cursor. An interface so the loop can be tested without one.
type Feeder interface {
	Feed(c project.Cursor) (project.Batch, error)
}

// Resumable is a Feeder that reads on from where the last tick's read stopped,
// so a tick fetches only what is newer (strata ADR-0025). The Since it hands
// back is kept with the cursor and handed to the next tick.
type Resumable interface {
	Feeder
	// FeedSince is Feed for a reader that last stopped at since. unmoved means
	// the store is exactly where since left it: nothing was read, and the batch
	// and next are empty.
	FeedSince(c project.Cursor, since strata.Since) (b project.Batch, next strata.Since, unmoved bool, err error)
}

// TickResult is what one round LANDED, not what it read: on any error the
// cursor is where the projection still stands and the counts are zero, because
// the transaction took nothing with it. A caller that logs a tick without
// branching on its error would otherwise name a generation that rolled back.
type TickResult struct {
	Cursor project.Cursor
	// Tick numbers the newest tick that wrote rows; see ChangedSince.
	Tick uint64
	// On a skip, Erased and Expired are the sets recorded with the tips.
	Erased  []erasure.Erasure
	Expired []project.Expiry

	// Seeded is records taken from a published generation, which arrive when a
	// projection is behind the newest one.
	Seeded int
	Ops    int
	// WritersWritten is the writer marks the tick moved, which is what its
	// cursor write costs; FieldsWritten is the field rows it wrote.
	WritersWritten int
	// WritersDropped is the marks of writers whose logs the store no longer
	// holds; see writeCursor.
	WritersDropped int
	FieldsWritten  int
	Skipped        bool
	LockWait       time.Duration
}

// Tick takes in what the store has done since this projection's cursor.
//
// Rows and cursor commit together, so a crash leaves the cursor behind them and
// never ahead: behind costs a batch re-applied, which the stamps make free.
//
// One advisory lock spans the whole cycle, cursor read through apply, so a
// store has one follower however many replicas consume. It spans the feed
// rather than only the write because a batch read before an erasure was
// published carries neither that erasure nor the filter that would have dropped
// its ops, and applying it afterwards puts the erased bytes back. So a Feeder
// that fetches must fetch inside Feed.
func (p *RecordProjection) Tick(ctx context.Context, f Feeder) (TickResult, error) {
	res, _, err := p.tick(ctx, f, false)
	return res, err
}

// TickAndRead is Tick, then a view that reads only the state that tick left: a
// repeatable-read snapshot taken before the lock is released, so no later tick
// shows through between two reads. release ends it; on error there is nothing
// to release.
func (p *RecordProjection) TickAndRead(ctx context.Context, f Feeder) (*RecordProjection, func(), TickResult, error) {
	res, view, err := p.tick(ctx, f, true)
	if err != nil {
		return nil, nil, res, err
	}
	return view.p, view.release, res, nil
}

type pinnedView struct {
	p       *RecordProjection
	release func()
}

// tick's results are named so the deferred unlock can withdraw the view: a
// failed unlock closes the session, and the snapshot with it.
func (p *RecordProjection) tick(ctx context.Context, f Feeder, pin bool) (_ TickResult, view *pinnedView, err error) {
	// Pinned, because an advisory lock belongs to the session that took it and
	// the transaction below has to run on that same session.
	conn, err := p.s.pool.Acquire(ctx)
	if err != nil {
		return TickResult{Cursor: project.NewCursor()}, nil, err
	}
	// A view owns the connection once returned.
	defer func() {
		if view == nil {
			conn.Release()
		}
	}()
	queued := time.Now()
	if _, err := conn.Exec(ctx, `SELECT pg_advisory_lock($1, $2)`, recordProjectionLockClass, p.lockKey()); err != nil {
		return TickResult{Cursor: project.NewCursor()}, nil, fmt.Errorf("store: locking the record projection: %w", err)
	}
	lockWait := time.Since(queued)
	defer func() {
		// Its own context: the caller's may be the one that just failed, and a
		// lock left held would stall every later tick for this store.
		unlockCtx, cancel := context.WithTimeout(context.WithoutCancel(ctx), advisoryUnlockTimeout)
		defer cancel()
		if _, uerr := conn.Exec(unlockCtx, `SELECT pg_advisory_unlock($1, $2)`,
			recordProjectionLockClass, p.lockKey()); uerr != nil {
			// The session still holds the lock. pgx keeps a connection whose
			// query was cancelled, so releasing it would return a locked
			// session to the pool and every later tick for this key would wait
			// on it until the pool happened to recycle it. A session lock dies
			// with its session, so end the session.
			slog.WarnContext(ctx, "record projection: unlock failed; discarding the connection",
				slog.Any("error", uerr), slog.String("schema", p.schemaName))
			_ = conn.Conn().Close(unlockCtx)
			if view != nil {
				view = nil
				err = fmt.Errorf("store: unlocking the record projection: %w", uerr)
			}
		}
	}()

	cursor, read, last, err := p.cursorOn(ctx, conn)
	if err != nil {
		return TickResult{Cursor: project.NewCursor()}, nil, err
	}
	tick := read.tick
	resumable, ok := f.(Resumable)
	if !ok {
		resumable = whole{f}
	}
	batch, since, unmoved, err := resumable.FeedSince(cursor, last.Since)
	if err != nil {
		return TickResult{Cursor: cursor}, nil, fmt.Errorf("store: reading the record feed: %w", err)
	}
	if unmoved {
		res := TickResult{Cursor: cursor, Erased: last.Erased, Expired: last.expired, Tick: uint64(tick),
			Skipped: true, LockWait: lockWait}
		return p.finish(ctx, conn, res, pin)
	}
	// What every failure below returns: a tick that did not commit moved nothing.
	unchanged := TickResult{Cursor: cursor}

	tx, err := conn.Begin(ctx)
	if err != nil {
		return unchanged, nil, err
	}
	defer func() { _ = tx.Rollback(ctx) }()

	// Only seeds and ops write rows; a batch of neither takes no number.
	if len(batch.Seed) > 0 || len(batch.Ops) > 0 {
		tick++
	}
	sink := &recordSink{p: p, ctx: ctx, tx: tx, tick: tick}
	next, err := project.Apply(sink, batch)
	if err == nil {
		err = sink.flush()
	}
	if err != nil {
		return unchanged, nil, fmt.Errorf("store: applying a record batch: %w", err)
	}
	written, dropped, err := p.writeCursor(ctx, tx, next, tick, read, stoppedAt{Since: since, expired: batch.Expired})
	if err != nil {
		return unchanged, nil, err
	}
	if err := tx.Commit(ctx); err != nil {
		return unchanged, nil, err
	}
	// The cursor answered is the one stored, which a read's tip is a hash of:
	// one still naming a dropped writer would differ from the next skip's.
	if len(dropped) > 0 {
		next = next.Clone()
		for _, w := range dropped {
			delete(next.Writers, w)
		}
	}
	res := TickResult{Cursor: next, Seeded: len(batch.Seed), Ops: len(batch.Ops), Erased: batch.Erased,
		Expired: batch.Expired, Tick: uint64(tick), WritersWritten: written, WritersDropped: len(dropped), FieldsWritten: sink.written,
		LockWait: lockWait}
	return p.finish(ctx, conn, res, pin)
}

func (p *RecordProjection) finish(ctx context.Context, conn *pgxpool.Conn, res TickResult, pin bool) (TickResult, *pinnedView, error) {
	if !pin {
		return res, nil, nil
	}
	view, err := p.snapshotOn(ctx, conn)
	if err != nil {
		return res, nil, err
	}
	return res, view, nil
}

// stoppedAt is where a tick's read stopped, which the next one reads on from,
// and the expiries it restated, which a skipped tick answers with. The sets are
// only kept with tips: a plain Feeder's batch need not restate the store's
// whole sets, and without tips the next tick reads whole anyway.
type stoppedAt struct {
	strata.Since
	expired []project.Expiry
}

// whole adapts a plain Feeder: every tick reads everything and records no tips.
type whole struct{ Feeder }

func (w whole) FeedSince(c project.Cursor, _ strata.Since) (project.Batch, strata.Since, bool, error) {
	b, err := w.Feed(c)
	return b, strata.Since{}, false, err
}

// snapshotOn runs a statement to fix the snapshot while the lock is still held:
// repeatable read takes it at the first statement, not at BEGIN.
func (p *RecordProjection) snapshotOn(ctx context.Context, conn *pgxpool.Conn) (*pinnedView, error) {
	rtx, err := conn.BeginTx(ctx, pgx.TxOptions{IsoLevel: pgx.RepeatableRead, AccessMode: pgx.ReadOnly})
	if err != nil {
		return nil, fmt.Errorf("store: opening a record projection snapshot: %w", err)
	}
	if _, err := rtx.Exec(ctx, `SELECT 1`); err != nil {
		_ = rtx.Rollback(context.WithoutCancel(ctx))
		return nil, fmt.Errorf("store: opening a record projection snapshot: %w", err)
	}
	out := p.WithContext(ctx)
	out.q = rtx
	var once sync.Once
	return &pinnedView{p: out, release: func() {
		once.Do(func() {
			// Its own context: the caller's is often done by now.
			rctx, cancel := context.WithTimeout(context.WithoutCancel(ctx), advisoryUnlockTimeout)
			defer cancel()
			if err := rtx.Rollback(rctx); err != nil {
				_ = conn.Conn().Close(rctx)
			}
			conn.Release()
		})
	}}, nil
}

// Cursor reads where this projection stands. One nothing has been fed returns
// the zero cursor, which asks for everything.
func (p *RecordProjection) Cursor(ctx context.Context) (project.Cursor, error) {
	c, _, _, err := p.cursorOn(ctx, p.s.pool)
	return c, err
}

// querier is the overlap of the pool and a pinned connection, so a tick reads
// its cursor on the session it already holds. Drawing two more while holding one
// is, at saturation, a tick waiting for a connection it can only get by
// releasing the one it is locked on.
type querier interface {
	QueryRow(context.Context, string, ...any) pgx.Row
	Query(context.Context, string, ...any) (pgx.Rows, error)
}

// cursorOn also returns the row as read, which writeCursor compares against,
// and where the last tick stopped.
func (p *RecordProjection) cursorOn(ctx context.Context, q querier) (project.Cursor, position, stoppedAt, error) {
	c := project.NewCursor()
	var read position
	var last stoppedAt
	var expired, erased []byte
	err := q.QueryRow(ctx,
		`SELECT generation, tick, tips, expired, erased FROM repo_record_cursors
		 WHERE repo_id = $1 AND schema_name = $2`,
		p.repoID, p.schemaName).Scan(&c.Generation, &read.tick, &read.tips, &expired, &erased)
	switch {
	case err == pgx.ErrNoRows:
		return c, position{}, stoppedAt{}, nil
	case err != nil:
		return c, position{}, stoppedAt{}, err
	}
	read.generation = c.Generation
	// Tips without both sets are not a place to read on from: the next read
	// would restate erasures it was never handed. A replica from before tips
	// writes the sets and leaves tips alone, so the two can drift apart.
	if read.tips != nil && expired != nil && erased != nil {
		if err := json.Unmarshal(read.tips, &last.Tips); err != nil {
			return c, position{}, stoppedAt{}, fmt.Errorf("store: reading the record projection's tips: %w", err)
		}
		if err := json.Unmarshal(expired, &last.expired); err != nil {
			return c, position{}, stoppedAt{}, fmt.Errorf("store: reading the record projection's expiries: %w", err)
		}
		if err := json.Unmarshal(erased, &last.Erased); err != nil {
			return c, position{}, stoppedAt{}, fmt.Errorf("store: reading the record projection's erasures: %w", err)
		}
	}
	rows, err := q.Query(ctx,
		`SELECT writer, seq FROM repo_record_cursor_writers WHERE repo_id = $1 AND schema_name = $2`,
		p.repoID, p.schemaName)
	if err != nil {
		return c, position{}, stoppedAt{}, err
	}
	defer rows.Close()
	// Twice, because the cursor goes to a Feeder, which may advance it in place.
	read.writers = map[string]uint64{}
	for rows.Next() {
		var writer string
		var seq int64
		if err := rows.Scan(&writer, &seq); err != nil {
			return c, position{}, stoppedAt{}, err
		}
		c.Writers[writer], read.writers[writer] = uint64(seq), uint64(seq)
	}
	return c, read, last, rows.Err()
}

// position is the row as a tick read it.
type position struct {
	generation uint64
	tick       int64
	tips       []byte
	// writers is the marks as read.
	writers map[string]uint64
}

// unmoved is whether repo_record_cursors still holds the generation, tick and
// tips a tick read, given as the parameters that carry them.
func unmoved(generation, tick, tips string) string {
	return `(repo_record_cursors.generation = ` + generation + ` AND repo_record_cursors.tick = ` + tick + `
	         AND repo_record_cursors.tips IS NOT DISTINCT FROM ` + tips + `::jsonb)`
}

// writeCursor only moves the cursor forward; followed_at moves with the
// generation. The tips are recorded only if the row still holds what the tick
// read: otherwise another tick wrote in between, and these tips may be older
// than the rows. It returns how many writer marks it wrote, and the writers
// whose marks it dropped.
func (p *RecordProjection) writeCursor(ctx context.Context, tx pgx.Tx, c project.Cursor, tick int64, read position, stopped stoppedAt) (int, []string, error) {
	b := &pgx.Batch{}
	var tips, expired, erased []byte
	var dropped []string
	writers, seqs := advanced(read.writers, c.Writers)
	if stopped.Tips != nil {
		var err error
		if tips, err = json.Marshal(stopped.Tips); err != nil {
			return 0, nil, fmt.Errorf("store: encoding the record projection's tips: %w", err)
		}
		expired, erased = marshalJSONArrayOrEmpty(stopped.expired), marshalJSONArrayOrEmpty(stopped.Erased)
		// A mark makes Cursor.Seen true for ops already consumed, so dropping
		// one has Feed resend them while the writer's log still holds them. Only
		// Retire deletes a writer's last log, and only once a generation covers
		// everything it wrote; its ops then arrive only as a seed, which no mark
		// filters. One-shot writers make a writer per write, so the marks would
		// otherwise grow with every write the store has taken.
		//
		// The test is that no log of the writer is among the tips, not that a ref
		// went: a prune deletes a rotation too, and the writer lives on in the next.
		// First in the batch, and guarded like the tips, against the row as read.
		if gone := retired(read.writers, writers, stopped.Tips); len(gone) > 0 {
			b.Queue(
				`DELETE FROM repo_record_cursor_writers
				 WHERE repo_id = $1 AND schema_name = $2 AND writer = ANY($3::text[])
				   AND EXISTS (SELECT 1 FROM repo_record_cursors
				               WHERE repo_id = $1 AND schema_name = $2 AND `+unmoved("$4", "$5", "$6")+`)
				 RETURNING writer`,
				p.repoID, p.schemaName, gone, int64(read.generation), read.tick, read.tips,
			).Query(func(rows pgx.Rows) (err error) {
				dropped, err = pgx.CollectRows(rows, pgx.RowTo[string])
				return err
			})
		}
	}
	guard := unmoved("$8", "$9", "$10")
	b.Queue(
		`INSERT INTO repo_record_cursors (repo_id, schema_name, generation, tick, tips, expired, erased)
		 VALUES ($1, $2, $3, $4, $5, $6, $7)
		 ON CONFLICT (repo_id, schema_name) DO UPDATE SET
		     generation = GREATEST(repo_record_cursors.generation, EXCLUDED.generation),
		     tick = GREATEST(repo_record_cursors.tick, EXCLUDED.tick),
		     followed_at = CASE WHEN EXCLUDED.generation > repo_record_cursors.generation
		                        THEN now() ELSE repo_record_cursors.followed_at END,
		     tips = CASE WHEN `+guard+` THEN EXCLUDED.tips ELSE NULL END,
		     expired = CASE WHEN `+guard+` THEN EXCLUDED.expired ELSE NULL END,
		     erased = CASE WHEN `+guard+` THEN EXCLUDED.erased ELSE NULL END`,
		p.repoID, p.schemaName, int64(c.Generation), tick, tips, expired, erased,
		int64(read.generation), read.tick, read.tips)
	// Every write is guarded to move forward only. A cursor is a high-water
	// mark, and two ticks for one store can overlap -- Put's row locks serialise
	// them per field, not per projection -- so an older one committing last
	// would otherwise walk the mark backwards and have Feed resend what is
	// already applied. One comparison per value, which is all a mark needs.
	//
	// Feed clones the cursor it was handed and only Advances it, so what comes
	// back is a superset, and only the marks that moved past what the tick read
	// are written: the rest are already there, at that value or above it, and
	// the guard would leave them as they are. A store keeps a mark for every
	// writer it holds a log of, so writing them all was one statement per writer
	// per tick.
	if len(writers) > 0 {
		b.Queue(
			`INSERT INTO repo_record_cursor_writers (repo_id, schema_name, writer, seq)
			 SELECT $1, $2, w, s FROM unnest($3::text[], $4::bigint[]) AS u(w, s)
			 ON CONFLICT (repo_id, schema_name, writer) DO UPDATE SET seq = EXCLUDED.seq
			 WHERE EXCLUDED.seq > repo_record_cursor_writers.seq`,
			p.repoID, p.schemaName, writers, seqs)
	}
	if err := tx.SendBatch(ctx, b).Close(); err != nil {
		return 0, nil, err
	}
	return len(writers), dropped, nil
}

// retired is the writers with a mark in read and no log among tips, less those
// this tick advanced, whose marks it writes. Sorted, so the statement locks its
// rows in one order.
func retired(read map[string]uint64, advanced []string, tips map[string]string) []string {
	live := map[string]bool{}
	for _, w := range advanced {
		live[w] = true
	}
	for ref := range tips {
		if r := reflayout.Parse(ref); r.Kind == reflayout.LogRotation {
			live[r.Writer] = true
		}
	}
	var gone []string
	for w := range read {
		if !live[w] {
			gone = append(gone, w)
		}
	}
	slices.Sort(gone)
	return gone
}

// advanced is the writers whose mark in next is past the one in read, a writer
// read lacks counting as at zero. Sorted, so the statement locks its rows in
// one order.
func advanced(read, next map[string]uint64) ([]string, []int64) {
	var writers []string
	for w, seq := range next {
		if seq > read[w] {
			writers = append(writers, w)
		}
	}
	slices.Sort(writers)
	seqs := make([]int64, len(writers))
	for i, w := range writers {
		seqs[i] = int64(next[w])
	}
	return writers, seqs
}

// recordSink applies one batch. Per-transaction, because that is its lifetime.
//
// Puts are held and written in flushes, a few statements for many fields,
// rather than two round trips per field. A flush comes before every other kind
// of write that deletes fields -- an expiry or erasure must find what the puts
// before it wrote -- at flushAt held fields, and at the end of the batch, which
// tick calls.
type recordSink struct {
	p    *RecordProjection
	ctx  context.Context
	tx   pgx.Tx
	tick int64

	pending map[fieldKey]slot
	// written counts the field rows written, for the tick's span.
	written int
}

type fieldKey struct{ typ, id, field string }

// slot is one field's class and value, held or stored.
type slot struct {
	class record.Class
	v     record.Value
}

// flushAt bounds a flush: how many rows one statement locks, and how big its
// arrays get when a projection is seeded from a large generation.
const flushAt = 1000

// Put writes a value if it supersedes what is stored.
//
// It asks record.Supersedes rather than expressing the rule in SQL, because the
// rule is three rules -- latest wins for the mutable class, EARLIEST for a fact,
// (version, payload, stamp) for a mirrored one -- under a class ordering that
// Supersedes does not carry and project.Memory applies first. Restating that in
// SQL is the derivation strata's conformance cases exist to catch.
//
// Two puts to one field in a flush are decided here, the way project.Memory
// decides them, so only the winner reaches the table.
func (s *recordSink) Put(k record.Key, class record.Class, field string, v record.Value) error {
	key := fieldKey{k.Type, k.ID, field}
	if held, ok := s.pending[key]; ok && !recordSupersedes(held.class, held.v, class, v) {
		return nil
	}
	if s.pending == nil {
		s.pending = map[fieldKey]slot{}
	}
	s.pending[key] = slot{class, v}
	if len(s.pending) >= flushAt {
		return s.flush()
	}
	return nil
}

// flush writes the held puts that supersede what is stored.
//
// The read takes the rows' locks, which is what makes deciding in Go safe: two
// ticks for one store can overlap, and without it both read the same prior
// value, both conclude they win, and the later commit takes the row whatever
// its stamp said. SetDeleteFloor closes the same race in its WHERE, which works
// there because it compares one stamp.
//
// At most twice: an insert that lands nothing found a row a concurrent tick
// inserted after the read, and the second pass locks that row and decides
// against it. Keys this pass did insert come back as rows they do not
// supersede, so retrying them all is a no-op for those.
func (s *recordSink) flush() error {
	pending := s.pending
	s.pending = nil
	for attempt := 0; attempt < 2; attempt++ {
		if len(pending) == 0 {
			return nil
		}
		var err error
		if pending, err = s.flushOnce(pending); err != nil {
			return err
		}
	}
	if len(pending) > 0 {
		return fmt.Errorf("store: %d record fields were neither insertable nor lockable", len(pending))
	}
	return nil
}

// flushOnce writes pending in two round trips: one to read and lock what is
// stored, one for the updates and inserts that win. It hands back the puts
// whose insert lost to a concurrent one, or nil.
func (s *recordSink) flushOnce(pending map[fieldKey]slot) (map[fieldKey]slot, error) {
	// Sorted, so the inserts take their keys in one order.
	keys := slices.SortedFunc(maps.Keys(pending), func(a, b fieldKey) int {
		return cmp.Or(strings.Compare(a.typ, b.typ), strings.Compare(a.id, b.id), strings.Compare(a.field, b.field))
	})
	held, err := s.heldForUpdate(keys)
	if err != nil {
		return nil, err
	}
	var updates, inserts fieldRows
	for _, k := range keys {
		put := pending[k]
		if h, ok := held[k]; !ok {
			inserts.add(k, put)
		} else if recordSupersedes(h.class, h.v, put.class, put.v) {
			updates.add(k, put)
		}
	}

	// Neither touches the other's rows: an update is for a row the read found,
	// an insert for one it did not.
	b := &pgx.Batch{}
	if len(updates.keys) > 0 {
		b.Queue(`UPDATE repo_record_fields f SET
		             value = u.value, version = u.version, deleted = u.deleted, class = u.class,
		             lamport = u.lamport, writer = u.writer, seq = u.seq, tick = $3
		         FROM `+fieldRowsUnnest+`
		         WHERE f.repo_id = $1 AND f.schema_name = $2
		           AND f.type = u.type AND f.id = u.id AND f.field = u.field`,
			s.rowArgs(updates)...).Exec(func(tag pgconn.CommandTag) error {
			s.written += int(tag.RowsAffected())
			return nil
		})
	}
	var lost bool
	if len(inserts.keys) > 0 {
		// DO NOTHING rather than DO UPDATE: a concurrent tick may have inserted
		// between the read and here, and overwriting its row is the clobber
		// this avoids.
		b.Queue(`INSERT INTO repo_record_fields
		             (repo_id, schema_name, tick, type, id, field, value, version, deleted, class, lamport, writer, seq)
		         SELECT $1, $2, $3, u.* FROM `+fieldRowsUnnest+`
		         ON CONFLICT (repo_id, schema_name, type, id, field) DO NOTHING`,
			s.rowArgs(inserts)...).Exec(func(tag pgconn.CommandTag) error {
			s.written += int(tag.RowsAffected())
			lost = int(tag.RowsAffected()) < len(inserts.keys)
			return nil
		})
	}
	if err := s.tx.SendBatch(s.ctx, b).Close(); err != nil {
		return nil, err
	}
	if !lost {
		return nil, nil
	}
	retry := make(map[fieldKey]slot, len(inserts.keys))
	for _, k := range inserts.keys {
		retry[k] = pending[k]
	}
	return retry, nil
}

// fieldRowsUnnest is rowArgs from $4 on, as a relation u.
const fieldRowsUnnest = `unnest($4::text[], $5::text[], $6::text[], $7::bytea[], $8::bytea[], $9::bool[],
		             $10::smallint[], $11::bigint[], $12::text[], $13::bigint[])
		         AS u(type, id, field, value, version, deleted, class, lamport, writer, seq)`

// fieldRows is puts as column arrays, for fieldRowsUnnest.
type fieldRows struct {
	keys           []fieldKey
	typ, id, field []string
	value, version [][]byte
	deleted        []bool
	class          []int16
	lamport, seq   []int64
	writer         []string
}

func (r *fieldRows) add(k fieldKey, p slot) {
	r.keys = append(r.keys, k)
	r.typ, r.id, r.field = append(r.typ, k.typ), append(r.id, k.id), append(r.field, k.field)
	r.value, r.version = append(r.value, p.v.Bytes), append(r.version, p.v.Version)
	r.deleted, r.class = append(r.deleted, p.v.Deleted), append(r.class, int16(p.class))
	r.lamport, r.writer, r.seq = append(r.lamport, int64(p.v.Stamp.L)), append(r.writer, p.v.Stamp.Writer), append(r.seq, int64(p.v.Stamp.Seq))
}

func (s *recordSink) rowArgs(r fieldRows) []any {
	return []any{s.p.repoID, s.p.schemaName, s.tick,
		r.typ, r.id, r.field, r.value, r.version, r.deleted, r.class, r.lamport, r.writer, r.seq}
}

// heldForUpdate reads the stored values of keys and holds their rows for this
// transaction. A key with no row is absent from the map. A join rather than
// IN, so each key is a primary-key probe rather than a candidate for a scan of
// the schema's rows.
func (s *recordSink) heldForUpdate(keys []fieldKey) (map[fieldKey]slot, error) {
	types, ids, fields := make([]string, len(keys)), make([]string, len(keys)), make([]string, len(keys))
	for i, k := range keys {
		types[i], ids[i], fields[i] = k.typ, k.id, k.field
	}
	rows, err := s.tx.Query(s.ctx,
		`SELECT f.type, f.id, f.field, f.class, f.value, f.version, f.deleted, f.lamport, f.writer, f.seq
		 FROM unnest($3::text[], $4::text[], $5::text[]) AS u(type, id, field)
		 JOIN repo_record_fields f
		   ON f.repo_id = $1 AND f.schema_name = $2
		  AND f.type = u.type AND f.id = u.id AND f.field = u.field
		 ORDER BY f.type, f.id, f.field
		 FOR UPDATE OF f`,
		s.p.repoID, s.p.schemaName, types, ids, fields)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	held := make(map[fieldKey]slot, len(keys))
	for rows.Next() {
		var k fieldKey
		var h slot
		var class int16
		var lamport, seq int64
		if err := rows.Scan(&k.typ, &k.id, &k.field, &class, &h.v.Bytes, &h.v.Version, &h.v.Deleted,
			&lamport, &h.v.Stamp.Writer, &seq); err != nil {
			return nil, err
		}
		h.class, h.v.Stamp.L, h.v.Stamp.Seq = record.Class(class), uint64(lamport), uint64(seq)
		held[k] = h
	}
	return held, rows.Err()
}

// recordSupersedes is project.Memory's rule, which is the one every projection
// owes the others. Class first, then the class's own rule.
func recordSupersedes(heldClass record.Class, held record.Value, nextClass record.Class, next record.Value) bool {
	if heldClass != nextClass {
		return nextClass > heldClass
	}
	return record.Supersedes(nextClass, held, next)
}

// Delete records that a value was unbound. A tombstone is a row carrying a
// stamp and nothing else, because a later write has to be able to beat it.
func (s *recordSink) Delete(k record.Key, field string, v record.Value) error {
	return s.Put(k, record.ClassMutable, field, record.Value{Stamp: v.Stamp, Deleted: true})
}

// SetDeleteFloor need not flush: a floor is its own table, and hides fields by
// comparison at read time rather than by touching them.
func (s *recordSink) SetDeleteFloor(k record.Key, floor stamp.Stamp) error {
	_, err := s.tx.Exec(s.ctx,
		`INSERT INTO repo_record_floors (repo_id, schema_name, type, id, lamport, writer, seq, tick)
		 VALUES ($1, $2, $3, $4, $5, $6, $7, $8)
		 ON CONFLICT (repo_id, schema_name, type, id) DO UPDATE SET
		     lamport = EXCLUDED.lamport, writer = EXCLUDED.writer, seq = EXCLUDED.seq, tick = EXCLUDED.tick
		 WHERE (EXCLUDED.lamport, EXCLUDED.writer, EXCLUDED.seq)
		     > (repo_record_floors.lamport, repo_record_floors.writer, repo_record_floors.seq)`,
		s.p.repoID, s.p.schemaName, k.Type, k.ID, int64(floor.L), floor.Writer, int64(floor.Seq), s.tick)
	return err
}

// Expire drops a type's facts decided below a Lamport value.
//
// Facts only, and by whole record: a fact binds to record.WholeRecord, so the
// row deciding whether a record expired is that field's. A cutoff rather than a
// list of what went, which is what lets it be re-applied.
func (s *recordSink) Expire(typ string, below uint64) error {
	if err := s.flush(); err != nil {
		return err
	}
	_, err := s.tx.Exec(s.ctx,
		`DELETE FROM repo_record_fields
		 WHERE repo_id = $1 AND schema_name = $2 AND type = $3 AND id IN (
		     SELECT id FROM repo_record_fields
		     WHERE repo_id = $1 AND schema_name = $2 AND type = $3
		       AND field = '' AND class = $4 AND lamport < $5)`,
		s.p.repoID, s.p.schemaName, typ, int16(record.ClassFact), int64(below))
	return err
}

// Erase removes what an erasure names, where the deciding stamp is below its
// bound.
//
// Fields only. A delete floor is a stamp rather than content -- it says a delete
// happened, not what was deleted -- so project.Memory and generation.Erase keep
// a non-zero one with nothing beside it. Sweeping an emptied floor would unhide
// the record the moment an older write arrived.
//
// The bound is the one part of erasure.Covers restated here; the rest is the
// shape of the WHERE clause.
func (s *recordSink) Erase(e erasure.Erasure) error {
	if err := s.flush(); err != nil {
		return err
	}
	args := []any{s.p.repoID, s.p.schemaName, e.Type, int64(e.Below)}
	where := `repo_id = $1 AND schema_name = $2 AND type = $3 AND lamport < $4`
	switch e.Kind {
	case erasure.ErasePartition:
		// A partition names itself and everything nested under it, by its own
		// field -- Partition, not ID, which a partition erasure leaves empty.
		where += ` AND (id = $5 OR (id > $6 AND id < $7))`
		args = append(args, e.Partition, e.Partition+"/", e.Partition+"0")
	case erasure.EraseField:
		// A field erasure never names the empty field, which is where a
		// mirrored value and a fact live -- see erasure.Names.
		where += ` AND id = $5 AND field = $6 AND field <> ''`
		args = append(args, e.ID, e.Field)
	default:
		where += ` AND id = $5`
		args = append(args, e.ID)
	}
	_, err := s.tx.Exec(s.ctx, `DELETE FROM repo_record_fields WHERE `+where, args...)
	return err
}

// Fields returns one record's visible fields, which is half of
// entire-records' store.Projection.
//
// Visible means bound and above the record's delete floor -- the same rule a
// fold applies, asked of rows instead of memory. A record exists if it has any
// field row at all, visible or not, which is why this reads the table and
// applies visibility here: a record whose fields are all hidden is one that
// currently shows nothing, not an absent one, and asking for only the visible
// ones would need a second query to tell those apart.
func (p *RecordProjection) Fields(typ, id string) (map[string][]byte, bool, error) {
	rows, err := p.reader().Query(p.readCtx(),
		`SELECT f.field, f.value, f.deleted,
		        (fl.repo_id IS NOT NULL AND NOT (f.lamport, f.writer, f.seq) > (fl.lamport, fl.writer, fl.seq))
		 FROM repo_record_fields f
		 LEFT JOIN repo_record_floors fl
		        ON fl.repo_id = f.repo_id AND fl.schema_name = f.schema_name
		       AND fl.type = f.type AND fl.id = f.id
		 WHERE f.repo_id = $1 AND f.schema_name = $2 AND f.type = $3 AND f.id = $4`,
		p.repoID, p.schemaName, typ, id)
	if err != nil {
		return nil, false, err
	}
	defer rows.Close()
	out, held := map[string][]byte{}, false
	for rows.Next() {
		var field string
		var value []byte
		var deleted, floored bool
		if err := rows.Scan(&field, &value, &deleted, &floored); err != nil {
			return nil, false, err
		}
		held = true
		if !deleted && !floored {
			out[field] = value
		}
	}
	return out, held, rows.Err()
}

// Under returns every record of one type at id or beneath it, with its visible
// fields.
//
// One statement, and a range rather than a scan. A nested record's id is its
// container's plus "/" and its own, so everything under a container sits in
// ["<id>/", "<id>0") -- '0' being the byte after '/'. The id column is C
// collation for exactly this: under a linguistic one the comparison does not
// mean what it means here.
func (p *RecordProjection) Under(typ, id string) (map[string]map[string][]byte, error) {
	rows, err := p.reader().Query(p.readCtx(),
		`SELECT f.id, f.field, f.value
		 FROM repo_record_fields f
		 LEFT JOIN repo_record_floors fl
		        ON fl.repo_id = f.repo_id AND fl.schema_name = f.schema_name
		       AND fl.type = f.type AND fl.id = f.id
		 WHERE f.repo_id = $1 AND f.schema_name = $2 AND f.type = $3
		   AND (f.id = $4 OR (f.id > $5 AND f.id < $6))
		   AND f.deleted = false
		   AND (fl.repo_id IS NULL OR (f.lamport, f.writer, f.seq) > (fl.lamport, fl.writer, fl.seq))`,
		p.repoID, p.schemaName, typ, id, id+"/", id+"0")
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	out := map[string]map[string][]byte{}
	for rows.Next() {
		var recordID, field string
		var value []byte
		if err := rows.Scan(&recordID, &field, &value); err != nil {
			return nil, err
		}
		at, ok := out[recordID]
		if !ok {
			at = map[string][]byte{}
			out[recordID] = at
		}
		at[field] = value
	}
	return out, rows.Err()
}

// ChangedSince names every record a tick after `tick` wrote, with the rows that
// moved. It cannot see what an expiry or erasure removed: those delete rows, so
// a caller compares those sets itself.
func (p *RecordProjection) ChangedSince(tick uint64) ([]recordchange.Record, error) {
	rows, err := p.reader().Query(p.readCtx(),
		`WITH changed AS (
		     SELECT type, id, field, value, deleted, writer FROM repo_record_fields
		     WHERE repo_id = $1 AND schema_name = $2 AND tick > $3
		 ), floors AS (
		     SELECT type, id, writer FROM repo_record_floors
		     WHERE repo_id = $1 AND schema_name = $2 AND tick > $3
		 ), keys AS (
		     SELECT type, id FROM changed UNION SELECT type, id FROM floors
		 )
		 SELECT k.type, k.id, c.field, c.value, COALESCE(c.deleted, false), COALESCE(c.writer, ''),
		        COALESCE(rose.writer, ''),
		        EXISTS (SELECT 1 FROM repo_record_fields f
		                LEFT JOIN repo_record_floors fl
		                       ON fl.repo_id = f.repo_id AND fl.schema_name = f.schema_name
		                      AND fl.type = f.type AND fl.id = f.id
		                WHERE f.repo_id = $1 AND f.schema_name = $2 AND f.type = k.type AND f.id = k.id
		                  AND f.tick <= $3 AND NOT f.deleted
		                  AND (fl.repo_id IS NULL OR (f.lamport, f.writer, f.seq) > (fl.lamport, fl.writer, fl.seq)))
		 FROM keys k
		 LEFT JOIN changed c ON c.type = k.type AND c.id = k.id
		 LEFT JOIN floors rose ON rose.type = k.type AND rose.id = k.id
		 ORDER BY k.type, k.id`,
		p.repoID, p.schemaName, int64(tick))
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var out []recordchange.Record
	for rows.Next() {
		var key record.Key
		var field *string
		var f recordchange.Field
		var floorWriter string
		var held bool
		if err := rows.Scan(&key.Type, &key.ID, &field, &f.Value, &f.Deleted, &f.Writer, &floorWriter, &held); err != nil {
			return nil, err
		}
		if n := len(out); n == 0 || out[n-1].Key != key {
			out = append(out, recordchange.Record{Key: key, FloorWriter: floorWriter, Held: held})
		}
		if field != nil {
			f.Field = *field
			out[len(out)-1].Fields = append(out[len(out)-1].Fields, f)
		}
	}
	return out, rows.Err()
}

func (p *RecordProjection) reader() querier {
	if p.q != nil {
		return p.q
	}
	return p.s.pool
}

// readCtx is the context the two Projection reads run under.
//
// store.Projection takes none -- it is entire-records' interface, shaped for a
// fold that cannot block -- so the one a projection was built with is used.
// Bound at construction rather than per call, because the interface beneath
// has no room for one.
func (p *RecordProjection) readCtx() context.Context {
	if p.ctx == nil {
		return context.Background()
	}
	return p.ctx
}

// Visible answers what a reader would see at one slot, stamp included.
//
// Fields answers the decode's question, names and bytes for one record. This
// answers a conformance harness's: one slot at a time, plus the stamp that
// decided it, which a suite comparing two projections has to see.
func (p *RecordProjection) Visible(k record.Key, field string) (record.Value, bool, error) {
	var v record.Value
	var lamport, seq int64
	var deleted bool
	err := p.reader().QueryRow(p.readCtx(),
		`SELECT f.value, f.version, f.deleted, f.lamport, f.writer, f.seq
		 FROM repo_record_fields f
		 LEFT JOIN repo_record_floors fl
		        ON fl.repo_id = f.repo_id AND fl.schema_name = f.schema_name
		       AND fl.type = f.type AND fl.id = f.id
		 WHERE f.repo_id = $1 AND f.schema_name = $2 AND f.type = $3 AND f.id = $4 AND f.field = $5
		   AND (fl.repo_id IS NULL OR (f.lamport, f.writer, f.seq) > (fl.lamport, fl.writer, fl.seq))`,
		p.repoID, p.schemaName, k.Type, k.ID, field).
		Scan(&v.Bytes, &v.Version, &deleted, &lamport, &v.Stamp.Writer, &seq)
	switch {
	case errors.Is(err, pgx.ErrNoRows):
		return record.Value{}, false, nil
	case err != nil:
		// Before the deleted check, so a Scan that failed half-way cannot be
		// read as an answer.
		return record.Value{}, false, err
	case deleted:
		return record.Value{}, false, nil
	}
	v.Stamp.L, v.Stamp.Seq = uint64(lamport), uint64(seq)
	return v, true, nil
}

// Apply takes a batch a caller already holds, which Tick is otherwise the only
// route to. A conformance harness has its own; so would a backfill replaying a
// captured feed.
func (p *RecordProjection) Apply(ctx context.Context, b project.Batch) error {
	_, err := p.Tick(ctx, heldBatch{b})
	return err
}

// heldBatch is a Feeder over a batch somebody else built.
type heldBatch struct{ b project.Batch }

func (h heldBatch) Feed(project.Cursor) (project.Batch, error) { return h.b, nil }

