package httpapi

// GET /repos/{repo_id}/records/{schema}/changes: what a records store does after
// a collections read, as SSE. See docs/adr/0009. The ref-event hub is only a
// doorbell; what changed is read from the projection.

import (
	"context"
	"errors"
	"net/http"
	"time"

	"github.com/danielgtaylor/huma/v2"

	"github.com/entirehq/entire-records/recordapi"
	"github.com/entirehq/strata/reflayout"

	"github.com/entirehq/entire-api/internal/records"
)

// RepoRecordsChangesInput is GET /repos/{repo_id}/records/{schema}/changes.
type RepoRecordsChangesInput struct {
	RepoID       string   `path:"repo_id" doc:"Repo id: placement ULID or public repo_<group ULID>"`
	Schema       string   `path:"schema" doc:"Schema name"`
	ChangesToken string   `query:"changes_token" doc:"The changesToken of a collections read: stream what changes after the state it was read from. Ignored when Last-Event-ID is sent."`
	LastEventID  string   `header:"Last-Event-ID" doc:"The id of the last changed frame received, which an EventSource sends when it reconnects. Takes precedence over changes_token."`
	Types        []string `query:"types,explode" doc:"Type names to report (repeatable or comma-separated). Omit for every type."`
}

type recordsChangedData struct {
	Tip     string                `json:"tip"`
	Patches []records.RecordPatch `json:"patches"`
	Records []recordapi.RecordDTO `json:"records"`
	Deleted []recordapi.RecordRef `json:"deleted"`
}

type recordsChangesReader func(ctx context.Context, token string) (records.ChangesResult, error)

func registerRepoRecordsChanges(api huma.API, deps *RepoActivityDeps) {
	gate := repoReadGate(api, deps)
	op := teamOp(api, "repoRecordsChanges", http.MethodGet, "/repos/{repo_id}/records/{schema}/changes",
		"Stream what changes in a records store after a read", "records", gate)
	op.Errors = withExtraErrors(op.Errors, http.StatusBadRequest, http.StatusNotFound, http.StatusBadGateway, http.StatusServiceUnavailable)

	authCache := newTTLCache[bool](changeAuthCacheMax, ssePollInterval)

	huma.Register(api, op, func(ctx context.Context, in *RepoRecordsChangesInput) (*huma.StreamResponse, error) {
		reader, err := recordsReader(deps)
		if err != nil {
			return nil, err
		}
		if deps.RefEventsNATS == nil {
			return nil, huma.Error503ServiceUnavailable("live ref events not configured")
		}
		store, err := records.StoreOf(in.Schema)
		if err != nil {
			return nil, recordsHTTPError(err)
		}
		token := in.LastEventID
		if token == "" {
			token = in.ChangesToken
		}
		if token == "" {
			return nil, huma.Error400BadRequest("changes_token is required: pass the changesToken a collections read returned")
		}
		types := splitCSV(in.Types)
		read := func(rctx context.Context, token string) (records.ChangesResult, error) {
			return reader.Changes(rctx, in.RepoID, in.Schema, token, records.ChangesOptions{Types: types})
		}

		// Subscribed before the first read, so a move during it still rings.
		hubs := deps.refEventHubs()
		hub, err := hubs.acquire(in.RepoID)
		if err != nil {
			return nil, huma.Error503ServiceUnavailable("live ref events unavailable", err)
		}
		doorbell := hub.addDoorbell([]string{reflayout.For(store).Root().Prefix() + "/"})
		// Read before streaming, so a bad token or schema is a status, not a frame.
		first, err := read(ctx, token)
		if err != nil {
			hub.remove(doorbell)
			hubs.release(hub)
			return nil, recordsHTTPError(err)
		}

		repoID, userID := in.RepoID, callerCacheKey(ctx)
		seedStreamAuth(authCache, userID, repoID, true)
		authorized := cachedStreamAuth(authCache, userID, repoID, func(actx context.Context) (bool, error) {
			return repoPermissionAllowed(actx, deps, repoID, permRepoRead)
		})
		return &huma.StreamResponse{Body: func(hctx huma.Context) {
			defer hubs.release(hub)
			defer hub.remove(doorbell)
			// Not held for the stream's lifetime: it may be many records.
			answer := first
			first = records.ChangesResult{}
			recordsChangesConnection(hctx.Context(), openSSE(hctx), doorbell, authorized, read, answer)
		}}, nil
	})
}

func recordsChangesConnection(ctx context.Context, s *sseWriter, doorbell *refHubConn, authorized func(context.Context) (bool, error), read recordsChangesReader, first records.ChangesResult) {
	token, ok := sendRecordsChanges(s, first)
	if !ok {
		return
	}
	if !s.frame("ready", token, struct{}{}) {
		return
	}

	startedAt := time.Now()
	lastPing := startedAt
	lastAuthAt := startedAt.Add(-ssePollInterval)
	for ctx.Err() == nil {
		now := time.Now()
		if now.Sub(startedAt) > sseMaxDuration {
			s.frame("reconnect", "", sseReason("max_duration"))
			return
		}
		if now.Sub(lastAuthAt) >= ssePollInterval {
			lastAuthAt = now
			allowed, err := authorized(ctx)
			if err != nil || !allowed {
				s.frame("forbidden", "", sseReason("access_revoked"))
				return
			}
		}
		if now = time.Now(); now.Sub(lastPing) >= ssePingInterval {
			if !s.ping(now) {
				return
			}
			lastPing = now
		}
		rung, ok := waitForWake(ctx, doorbell.wake, nextConnTick(time.Now(), startedAt, lastPing, lastAuthAt))
		if !ok {
			return
		}
		if !rung {
			continue
		}
		// Even a ring naming no refs (the hub's NATS reconnect) reads: moves may have been missed.
		rang := doorbell.drain()
		res, err := read(ctx, token)
		if err != nil {
			if ctx.Err() == nil && !errors.Is(err, context.Canceled) {
				s.frame("error", "", sseError())
			}
			return
		}
		recordRingLag(ctx, "changes", rang, res)
		if token, ok = sendRecordsChanges(s, res); !ok {
			return
		}
	}
}

// nonNil encodes as [] rather than null.
func nonNil[T any](s []T) []T {
	if s == nil {
		return []T{}
	}
	return s
}

// sendRecordsChanges returns the token to read from next; ok is false once the stream is over.
func sendRecordsChanges(s *sseWriter, res records.ChangesResult) (token string, ok bool) {
	if res.Reload {
		s.frame("reload", "", sseReason("read_again"))
		return "", false
	}
	if res.Empty() {
		return res.Token, true
	}
	data := recordsChangedData{Tip: res.Tip, Patches: nonNil(res.Patches), Records: nonNil(res.Records), Deleted: nonNil(res.Deleted)}
	return res.Token, s.frame("changed", res.Token, data)
}

