package httpapi

import (
	"context"
	"errors"
	"fmt"
	"log/slog"
	"net/http"
	"net/url"

	"github.com/danielgtaylor/huma/v2"
	"github.com/entirehq/entire-records/recordapi"
	"github.com/entirehq/entire-records/schema"
	recstore "github.com/entirehq/entire-records/store"
	"github.com/entirehq/strata/git"

	"github.com/entirehq/entire-api/internal/auth"
	"github.com/entirehq/entire-api/internal/stratawrite"
)

// EnableStrataWrite must be called after the content transports are set.
func (deps *RepoActivityDeps) EnableStrataWrite() error {
	if deps.RepoAPIBase == "" {
		return nil
	}
	origin, err := deps.gitOrigin()
	if err != nil {
		return fmt.Errorf("strata write: %w", err)
	}
	deps.StrataRepoURL = func(repoID string) string { return origin + "/git/repo/" + url.PathEscape(repoID) }
	deps.EnableStrataSockets()
	return nil
}

// EnableStrataSockets is for a harness that sets StrataRepoURL itself.
func (deps *RepoActivityDeps) EnableStrataSockets() {
	if deps.StrataSockets == nil {
		deps.StrataSockets = newStrataSockets()
	}
}

// DrainStrataSockets ends every socket on this replica: http.Server.Shutdown
// doesn't wait for hijacked connections.
func (deps *RepoActivityDeps) DrainStrataSockets(ctx context.Context) error {
	if deps.StrataSockets == nil {
		return nil
	}
	return deps.StrataSockets.Shutdown(ctx)
}

// RepoStrataCreateInput is PUT /repos/{repo_id}/strata/{store}.
type RepoStrataCreateInput struct {
	RepoID string `path:"repo_id" doc:"Repo id: placement ULID or public repo_<group ULID>"`
	Store  string `path:"store" doc:"Store (schema) name"`
	Body   struct {
		Definition string `json:"definition" doc:"The schema definition file (YAML); its name must match {store}"`
	}
}

// RepoStrataCreateOutput is 204, or 202 when the schema may not have landed.
type RepoStrataCreateOutput struct{ Status int }

// RepoStrataEditsInput is POST /repos/{repo_id}/strata/{store}/edits.
type RepoStrataEditsInput struct {
	RepoID         string          `path:"repo_id" doc:"Repo id: placement ULID or public repo_<group ULID>"`
	Store          string          `path:"store" doc:"Store (schema) name"`
	IdempotencyKey string          `header:"Idempotency-Key" doc:"Optional replay-safe key; a retried request with the same key and body returns the cached response instead of re-executing."`
	Body           recordapi.Batch `doc:"Writes and deletes to land as one commit"`
}

type RepoStrataEditsOutput struct {
	// Status is 202 when the write may not have landed.
	Status              int
	IdempotencyReplayed string `header:"Idempotency-Replayed" doc:"true when an earlier request with the same Idempotency-Key wrote these records and nothing was written now; absent otherwise."`
	Body                struct {
		Written   []recordapi.RecordRef `json:"written"`
		Confirmed bool                  `json:"confirmed" doc:"false (with 202) when the write may or may not have landed: the push's answer was lost. Look for the written records before writing them again."`
	}
}

func (o *RepoStrataEditsOutput) markIdempotentReplay() { o.IdempotencyReplayed = "true" }

func (o *RepoStrataEditsOutput) responseStatus() int { return o.Status }

func registerRepoStrata(api huma.API, deps *RepoActivityDeps) {
	// Any cell: a strata write is a git push to the repo, which may enter at any
	// placement that holds it.
	createGate := repoGate(api, deps, placementNone, requireAuth(api, &deps.baseDeps), requireRepoManageSettings(api, deps))
	writeGate := repoGate(api, deps, placementNone, requireAuth(api, &deps.baseDeps), requireRepoPush(api, deps))
	extra := []int{http.StatusNotFound, http.StatusBadGateway}

	createOp := teamOp(api, "repoStrataCreate", http.MethodPut, "/repos/{repo_id}/strata/{store}",
		"Create a strata record store, or update its schema", "strata", createGate)
	createOp.Errors = withExtraErrors(createOp.Errors, append(extra, http.StatusConflict)...)
	createOp.DefaultStatus = http.StatusNoContent
	createOp.Responses = map[string]*huma.Response{"202": {Description: "The push's answer was lost, so the schema may or may not have landed. Sending it again is safe."}}
	huma.Register(api, createOp, func(ctx context.Context, in *RepoStrataCreateInput) (*RepoStrataCreateOutput, error) {
		r, err := strataRemote(ctx, deps, in.RepoID)
		if err != nil {
			return nil, err
		}
		desired, err := parseStrataSchema(in.Store, in.Body.Definition)
		if err != nil {
			return nil, huma.Error400BadRequest(err.Error())
		}
		err = r.Create(ctx, desired, strataAuthor(ctx))
		switch {
		case errors.Is(err, stratawrite.ErrUnconfirmed):
			slog.WarnContext(ctx, "strata schema unconfirmed", slog.Any("error", err))
			return &RepoStrataCreateOutput{Status: http.StatusAccepted}, nil
		case err != nil:
			return nil, strataHTTPError(err)
		}
		return &RepoStrataCreateOutput{Status: http.StatusNoContent}, nil
	})

	editsOp := teamOp(api, "repoStrataEdits", http.MethodPost, "/repos/{repo_id}/strata/{store}/edits",
		"Write a batch of records into a strata record store", "strata", writeGate)
	editsOp.Errors = withExtraErrors(editsOp.Errors, append(extra, http.StatusConflict)...)
	editsOp.Responses = map[string]*huma.Response{"202": {Description: "The push's answer was lost, so the write may or may not have landed; the body names what it wrote, with confirmed false."}}
	huma.Register(api, editsOp, withIdempotency(deps, http.StatusOK,
		func(in *RepoStrataEditsInput) string { return in.IdempotencyKey },
		func(in *RepoStrataEditsInput) string { return "strata:edits:" + in.RepoID + ":" + in.Store },
		func(ctx context.Context, in *RepoStrataEditsInput) (*RepoStrataEditsOutput, error) {
			r, err := strataRemote(ctx, deps, in.RepoID)
			if err != nil {
				return nil, err
			}
			written, err := r.OneShot(ctx, in.Store, in.Body, strataAuthor(ctx))
			out := &RepoStrataEditsOutput{Status: http.StatusOK}
			switch {
			case errors.Is(err, stratawrite.ErrUnconfirmed):
				slog.WarnContext(ctx, "strata write unconfirmed", slog.Any("error", err))
				out.Status = http.StatusAccepted
			case err != nil:
				return nil, strataHTTPError(err)
			default:
				out.Body.Confirmed = true
			}
			out.Body.Written = written
			return out, nil
		}))
}

func parseStrataSchema(store, definition string) (schema.Schema, error) {
	desired, err := schema.ParseFile([]byte(definition))
	if err != nil {
		return schema.Schema{}, err
	}
	if err := schema.ValidateFile(desired); err != nil {
		return schema.Schema{}, err
	}
	if desired.Name != store {
		return schema.Schema{}, fmt.Errorf("schema name %q does not match store %q", desired.Name, store)
	}
	return desired, nil
}

func strataRemote(ctx context.Context, deps *RepoActivityDeps, repoID string) (stratawrite.Remote, error) {
	if deps.StrataRepoURL == nil {
		return stratawrite.Remote{}, huma.Error404NotFound("strata writes need an entiredb upstream")
	}
	return stratawrite.Remote{URL: deps.StrataRepoURL(repoID), Client: contentHTTPClient(ctx, deps)}, nil
}

func strataAuthor(ctx context.Context) string {
	name, email := auth.CommitAuthor(ctx)
	return fmt.Sprintf("%s <%s>", name, email)
}

func strataHTTPError(err error) error {
	if errors.Is(err, recstore.ErrNoSchema) {
		return huma.Error404NotFound(err.Error())
	}
	if errors.Is(err, stratawrite.ErrSchemaRefused) || errors.Is(err, git.ErrRejected) {
		return huma.Error409Conflict(err.Error())
	}
	return recordsVerdict(err, "strata write failed")
}

