// Package authz decides whether a push may touch the refs it names.
//
// Write access to a repository is push access to every store in it. Nothing in
// the record protocol changes that: a store's refs are ordinary refs and git has
// no per-ref authorization. So the boundary a group actually gets is whatever the
// server enforces at receive time, and this package is the decision that
// enforcement makes — a pure function of a policy, an identity and the ref
// updates a push proposes.
//
// It is deliberately not a signing scheme. Signatures answer "who wrote this
// value", survive compaction, and are checked by readers; that lives on the
// record and outside the protocol. This answers "who may move this ref", is
// checked once at push time by the server, and protects the parts of the layout
// that no later reader could tell had been tampered with.
package authz

import (
	"fmt"
	"sort"
	"strconv"
	"strings"

	"github.com/entirehq/strata/reflayout"
)

// Update is one line of what a push proposes: a ref, what the server holds, and
// what the push would leave there. Old is all zeros for a creation and New is all
// zeros for a deletion, which is git's own convention on a hook's stdin.
type Update struct {
	Ref string
	Old string
	New string
}

// Creating reports whether the ref does not exist on the server yet.
func (u Update) Creating() bool { return isZero(u.Old) }

// Deleting reports whether the push would remove the ref.
func (u Update) Deleting() bool { return isZero(u.New) }

// isZero accepts both object-id widths, since a repository may be sha1 or sha256
// and a hook that only knew one would wave every creation through in the other.
func isZero(oid string) bool {
	if len(oid) != 40 && len(oid) != 64 {
		return false
	}
	return strings.Trim(oid, "0") == ""
}

