package refpolicy_test

import (
	"testing"

	"github.com/stretchr/testify/assert"
	"github.com/stretchr/testify/require"

	"entire.io/refpolicy"
)

func TestResolveCoverage(t *testing.T) {
	t.Parallel()
	for _, mode := range []string{refpolicy.CoverageDisabled, refpolicy.CoverageFull, refpolicy.CoverageDefaultBranch} {
		got, err := refpolicy.ResolveCoverage(mode)
		require.NoError(t, err)
		assert.Equal(t, mode, got, "a valid mode is returned unchanged")
		assert.True(t, refpolicy.ValidCoverage(mode))
	}

	// Unset is a legitimate "not configured", matching an unset trust lifecycle.
	got, err := refpolicy.ResolveCoverage("")
	require.NoError(t, err)
	assert.Equal(t, refpolicy.CoverageDisabled, got)

	// An unrecognized value is NOT a default. Silently choosing disabled would
	// drop entries a policy requires, and the gap is invisible because the
	// entry-number chain keeps advancing on the refs that are covered.
