func wireTrustPublisher(svc *adminapi.RepoAdminService, pw *rslstore.RSLWriter, pool *pgxpool.Pool) {
	if pw == nil {
		return
	}
	svc.TrustPublisher = pw
	svc.TrustRestorer = pw
	svc.TrustReceipts = adminapi.NewPgTrustReceiptStore(pool)
	svc.TrustPool = pool
}

// svcTokAdminWorkloads is the allowlist of mTLS workloads admitted on the
// :8281 admin mount. entire-core remains the original caller for the
// console's cluster-inspection RPCs (per the comment above the mount).
// entire-backup joins for the three backup RPCs (ListAllRepos,
// DirtyReposSince, StreamRepoRefDigests) so the k8s CronJob path can reach them
// over internal DNS without going through the public ALB on :443 — this
// closes the gRPC-over-Cloudflare reachability hole that blocks the
// apex-DNS path until infra #387 lands.
//
// The in-handler `requireBackupAdminAccess` guard (server/adminapi/service.go)
// independently checks that the Bearer JWT is a TokenBackupAccess and
// rejects entire-core's TokenOpsAccess on the three backup RPCs; the gate
// here only narrows acceptance at the cert layer.
//
// entire-mcp joins to reach the read forensics RPCs from the hosted MCP
// surface. Admitting the workload here is a cert-layer narrowing only: the
// admin RPCs still require a cnf-bound ops-access JWT, so the leaf alone
// grants nothing.
var svcTokAdminWorkloads = []servicetoken.Workload{
	servicetoken.WorkloadEntireCore,
	servicetoken.WorkloadEntireBackup,
	servicetoken.WorkloadEntireMCP,
}

// svcTokGitWorkloads is the allowlist for the /et/ and /git/ mounts on
// :8281. Tighter than svcTokAdminWorkloads on purpose — see the
// comment above the internalMux.Handle("/et/", ...) call site.
//
// WorkloadEntireDB is admitted so on-node DISS callers (repair queue,
// catchup scanner, StoreRepoProvider-backfill) can fetch from peers on
// this mount instead of the public apex (ADR 20260518). Their outbound
// mTLS bundle carries a positive SPIFFE URI SAN (ENT-599) —
// callerFromMTLS resolves it to WorkloadEntireDB via the normal SPIFFE
// path, same as any other in-cluster workload. No Bearer is presented
// or required: internalWorkloadFromCert below synthesises an internal
// workload principal from the cert alone (the JWT-issuance path that
// used to gate this mount was retired).
//
// WorkloadMirrorWorker is the cluster-internal GitHub-mirror sync workload.
// Like entiredb peer-fetch it is authorized cert-only — no Bearer — but from
// the svcTokWriteMirrorWorkloads allowlist below, which additionally grants
// push (to mirror-class repos).
//
// WorkloadPeregrine is authorized cert-only from svcTokReadAnyRepoWorkloads
// below (read-any-repo class).
//
// WorkloadEntireAPI is admitted for entire-api's git-meta receive-pack writes
// to refs/meta/entire/* (ENT-1106). WorkloadGate records its mTLS identity
// (servicetoken.CallerFromContext); receive-pack's namespaceWriters policy is
// what authorizes the write. See ADR 20260603-reserved-refs.md.
var svcTokGitWorkloads = []servicetoken.Workload{
	servicetoken.WorkloadEntireBackup,
	servicetoken.WorkloadEntireDB,
	servicetoken.WorkloadMirrorWorker,
	servicetoken.WorkloadPeregrine,
	servicetoken.WorkloadEntireAPI,
}

// svcTokWriteMirrorWorkloads is this server's inbound allowlist for the static
// write-mirror permission class (docs/auth.md §3.2): internal workloads whose
// mTLS/SPIFFE certificate is the whole credential for pushing to mirror-class
// repos. A caller here needs no Bearer token and no SpiceDB grant — the
// allowlist entry is the authority. certOnlyGitPrincipal synthesises a
// reqctx.KindInternalWorkload principal with WriteMirror set (pull
// cluster-wide, push allowed; receive-pack rejects the push unless the target
// repo is mirror-class) for a no-Bearer request from one of these workloads.
//
// mirror-worker republishes what it just fetched from the GitHub upstream; as
// an internal workload it holds no svc_* row, mints no token, and needs no
// per-repo writer grant. Membership is a subset of svcTokGitWorkloads — a
// workload must clear the cert gate before it can be authorized cert-only.
var svcTokWriteMirrorWorkloads = []servicetoken.Workload{
	servicetoken.WorkloadMirrorWorker,
}

// svcTokReadAnyRepoWorkloads is this server's inbound allowlist for the static
// read-any-repo permission class (docs/auth.md §3.2): the mTLS certificate
// alone authorizes cluster-wide pull, no Bearer and no SpiceDB grant.
// peregrine clones/fetches every repo for its search indexes and, as an
// internal workload, holds no svc_* row. Subset of svcTokGitWorkloads.
var svcTokReadAnyRepoWorkloads = []servicetoken.Workload{
	servicetoken.WorkloadPeregrine,
}

// svcTokRepoAPIWorkloads is the cert-layer allowlist (WorkloadGate) for the
// /api/v1/ huma repo-API mount on :8281 — which workloads may reach the mount
// at all. Tighter on purpose: adding a workload here exposes the structured
// repo-read surface to it, so it's a deliberate, reviewable one-liner. Pinned
// by TestSvcTokRepoAPIMountAllowedWorkloads. How each admitted workload then
// authorizes is decided in svcTokRepoAPIAuthMiddleware:
//
//   - entire-api and entire-search are authorized cert-only from
//     svcTokRepoReadWorkloads when they send no Bearer (docs/auth.md §3.2) —
//     no SpiceDB. The cert-only principal remains pull-only; CreateCommit has
//     a separate exact-workload capability gate in repoapi. entire-search
//     also forwards a per-user Bearer for its ordinary reads, which takes the
//     token path below.
//   - entire-mcp presents a Bearer JWT (per-user repo-scoped or account
//     access), so SpiceDB repo#pull is the real gate and the leaf alone
//     grants nothing.
//   - entire-api-gateway is entire-api's public reverse proxy. It always
//     forwards the caller's bearer, so it authorizes exactly like entire-mcp:
//     per-user, live against SpiceDB. It is a separate leaf from entire-api
//     so repoapi can tell a proxied user write from entire-api's own trail
//     merge; only the latter may bypass server-side-merge-only (COR-1916).
//     Keep it out of svcTokRepoReadWorkloads: a proxied request must never
//     be authorized cert-only.
//   - agent-insights is absent on purpose: it reads with installation tokens
//     on the public listener, so its SPIFFE leaf (its NATS identity) must not
//     reopen a cert-only bypass it no longer needs (ENT-2805).
var svcTokRepoAPIWorkloads = []servicetoken.Workload{
	servicetoken.WorkloadEntireAPI,
	servicetoken.WorkloadEntireAPIGateway,
	servicetoken.WorkloadEntireMCP,
	servicetoken.WorkloadEntireSearch,
}

// svcTokRepoReadWorkloads is this server's inbound allowlist for the static
// repo-read permission class (docs/auth.md §3.2): internal workloads whose
// mTLS/SPIFFE certificate is the whole credential for reading the structured
// repo API. A caller here needs no Bearer token and no SpiceDB grant — the
// allowlist entry is the authority. svcTokRepoAPIAuthMiddleware synthesises a
// reqctx.KindInternalWorkload principal (pull cluster-wide, ordinary push
// rejected) for a no-Bearer request from one of these workloads. repoapi's
// CreateCommit capability is checked separately against the exact entire-api
// SPIFFE caller and does not widen this principal.
//
// entire-api (the activity ingester) reads commits, refs, files and trees to
// attribute activity; as an internal workload it holds no svc_* row and mints
// no token. entire-search (semantic search indexer) needs cert-only access to
// /repos/resolve for bulk ULID resolution during backfill — the sa_session
// token it mints via client_credentials is a login JWT, which AcceptRepoAPIAuth
// rejects (chicken-and-egg: repo-scoped tokens need the ULID that /repos/resolve
// returns). Membership is a subset of svcTokRepoAPIWorkloads — a workload must
// clear the cert gate before it can be authorized cert-only.
var svcTokRepoReadWorkloads = []servicetoken.Workload{
	servicetoken.WorkloadEntireAPI,
	servicetoken.WorkloadEntireSearch,
}

// svcTokAdminMount returns the handler chain mounted at adminPath on the
// strict-mTLS :8281 listener: inflight tracker → workload gate → admin
// handler. Extracted as a named helper so the workload allowlist is
// testable in isolation (see svctok_listener_test.go) without standing
// up the full listener.
func svcTokAdminMount(trustDomain string, adminHandler http.Handler, inflight *sync.WaitGroup) http.Handler {
	return inflightTracker(inflight)(svctokserver.WorkloadGate(trustDomain, svcTokAdminWorkloads...)(adminHandler))
}

// svcTokRepoAdminMount returns the handler chain for the RepoAdmin mount
// on the strict-mTLS :8281 listener: inflight tracker → workload gate →
// JWT auth wrapper. Only entire-core may reach RepoAdmin.
//
// The WorkloadGate narrows the inbound cert to the entire-core workload
// at the cert layer so an entire-core-issued service:entiredb token
// presented over a different in-trust workload's client cert is
// rejected before JWT verification runs. Extracted as a named helper
// so the allowlist is pinned by a test (see svctok_listener_test.go)
// and can't be dropped silently.
func svcTokRepoAdminMount(trustDomain string, repoAdmin http.Handler, inflight *sync.WaitGroup) http.Handler {
	return inflightTracker(inflight)(svctokserver.WorkloadGate(trustDomain, servicetoken.WorkloadEntireCore)(repoAdmin))
}

