// Package refevents publishes ref-change notifications on NATS
// (the repo_refs_v1 stream), for EVERY repo, decoupled from whether the repo
// records a gittuf RSL. It owns the RefEvent wire format. Dedup identity
// derives from the ref-transition content (see NATSMsgID and
// RefEvent.DeliveryID), so no per-repo sequence counter is maintained.
//
// Two Sink implementations exist. Production uses the transactional Outbox +
// Relay pair (see outbox.go): the push transaction enqueues marshaled
// messages and the relay ships them after commit, guaranteeing at-least-once
// delivery of every committed ref change. The direct Emitter is best-effort
// (publish failures are logged and swallowed) and remains for environments
// without a PostgreSQL transaction around the ref write — the sim harness
// and unit tests.
package refevents

import (
	"bytes"
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"log/slog"
	"reflect"
	"slices"
	"strings"
	"time"
	"unicode/utf8"

	"entire.io/repositories"
	"entire.io/reqctx"
	"entire.io/slogutil"
	"github.com/go-git/go-git/v6/plumbing"
	"github.com/nats-io/nats.go"
)

// NATS stream / subject identity. Kept stable so existing consumers keep working.
const (
	NATSSubjectPrefix = "repo_refs_v1."
	NATSStreamName    = "repo_refs_v1"
)

// refEventVersion is the supported wire envelope version.
const refEventVersion = 1

// Wire values for RefEvent.RefOp.
const (
	RefOpCreate      = "create"
	RefOpUpdate      = "update"
	RefOpDelete      = "delete"
	RefOpForceUpdate = "force_update"
	// RefOpSymrefUpdate is a symbolic ref retargeting (today only HEAD, moved by
	// RepoAdmin.SetDefaultBranch on a default-branch change). It carries no
	// object motion: OldTarget/NewTarget stay empty and the transition is the
	// ref-name pair OldSymrefTarget → NewSymrefTarget. Additive: consumers that
	// filter on the other ops (or on refs/heads/ names) never match it.
	RefOpSymrefUpdate = "symref_update"
)

