package harness

import (
	"context"
	"encoding/json"
	"net/http"
	"net/url"

	"github.com/entirehq/entire-api/internal/recordprojection"
	"github.com/entirehq/entire-api/internal/records"
	"github.com/entirehq/entire-api/internal/stratagit"
)

// ReadsStrataPlans pages through this cell's records read of the planning
// store's plans and returns how many there are. The read comes from this cell's
// projection, caught up from its strata repository as EnableRecords catches it
// up from entiredb.
func (a cellAPI) ReadsStrataPlans(r *Repo) int {
	c := a.c
	t := c.w.t
	t.Helper()
	if c.strataDir == "" {
		t.Fatalf("%s has no strata repository to read", c.name)
	}
	if c.repoDeps.RecordsReader == nil {
		dir := c.strataDir
		c.repoDeps.RecordsReader = records.New(recordprojection.Reads{Store: c.repoDeps.Store,
			Remote: func(context.Context, string) stratagit.Remote { return stratagit.Remote{URL: dir} }})
	}
	n, token := 0, ""
	for {
		path := "/api/v0/repos/" + r.In(c) + "/records/planning/collections/plan?pageSize=100"
		if token != "" {
			path += "&pageToken=" + url.QueryEscape(token)
		}
		got := c.attempt(http.MethodGet, path, nil)
		if got.Status != http.StatusOK {
			t.Fatalf("%s: reading plans: HTTP %d: %s", c.name, got.Status, got.Body)
		}
		var page struct {
			Items []json.RawMessage `json:"items"`
			Next  string            `json:"nextPageToken"`
		}
		if err := json.Unmarshal([]byte(got.Body), &page); err != nil {
			t.Fatalf("%s: decoding plans: %v", c.name, err)
		}
		n += len(page.Items)
		if page.Next == "" {
			return n
		}
		token = page.Next
	}
}

// StrataGenerations is the oldest and newest generation of the planning store
// in this cell's strata repository, as a fresh clone sees them.
func (c *Cell) StrataGenerations() (oldest, newest uint64) {
	c.w.t.Helper()
	s, err := stratagit.Remote{URL: c.strataDir}.Open(context.Background(), "planning")
	if err != nil {
		c.w.t.Fatalf("%s: opening its strata store: %v", c.name, err)
	}
	report, err := s.Status()
	if err != nil {
		c.w.t.Fatalf("%s: surveying its strata store: %v", c.name, err)
	}
	return report.OldestGeneration, report.Generation
}

// AssertStrataGenerationDropped fails unless generation g is older than every
// generation this cell's strata repository still holds.
func (c *Cell) AssertStrataGenerationDropped(g uint64) {
	c.w.t.Helper()
	if oldest, newest := c.StrataGenerations(); oldest <= g {
		c.w.t.Fatalf("%s: generation %d is still held (%d..%d)", c.name, g, oldest, newest)
	}
}
